// 纪年：鲁公纪年 + 周王纪年（春秋通行以鲁君纪年）
const LU = [[-796, '孝公'], [-768, '惠公'], [-722, '隐公'], [-711, '桓公'], [-693, '庄公'], [-661, '闵公'], [-659, '僖公'], [-626, '文公'],
  [-608, '宣公'], [-590, '成公'], [-572, '襄公'], [-541, '昭公'], [-509, '定公'], [-494, '哀公'], [-467, '悼公']];
const ZHOU = [[-781, '幽王'], [-770, '平王'], [-719, '桓王'], [-696, '庄王'], [-681, '釐王'], [-676, '惠王'], [-651, '襄王'], [-618, '顷王'],
  [-612, '匡王'], [-606, '定王'], [-585, '简王'], [-571, '灵王'], [-544, '景王'], [-519, '敬王'], [-476, '元王'], [-468, '贞定王']];
function cnNumY(n) {
  const D = '〇一二三四五六七八九';
  if (n === 1) return '元';
  if (n < 10) return D[n];
  const t = Math.floor(n / 10), o = n % 10;
  return (t === 1 ? '' : D[t]) + '十' + (o ? D[o] : '');
}
function reignOf(L, y) { let r = L[0]; for (const it of L) if (it[0] <= y) r = it; return `${r[1]}${cnNumY(y - r[0] + 1)}年`; }
function chunqiuYear(y) { return [{ d: '鲁', s: reignOf(LU, y) }, { d: '周', s: reignOf(ZHOU, y) }]; }
// 事件的 zm 为《左传》所记周正月份：详情里显示“鲁某公某年某季某月”，时间轴月份折合为公历（约早一个月）
function zhouMonth(y, zm) {
  const s = ['春', '春', '春', '夏', '夏', '夏', '秋', '秋', '秋', '冬', '冬', '冬'][zm - 1];
  return `鲁${reignOf(LU, y)}${s}${zm === 1 ? '正' : cnNumY(zm).replace('元', '一')}月`;
}

