const EVENTS = [
  { y: -656, zm: 12, t: '骊姬之乱 · 申生自缢', p: '新城（曲沃）', m: '今山西闻喜', ll: [111.22, 35.36], k: 'pol', refs: ['左传', '晋世家'],
    d: '晋献公伐骊戎，得骊姬，宠爱无比，生奚齐。骊姬想立奚齐，设计陷害太子申生：让申生祭祀生母，把祭肉献给献公，自己暗中下毒。献公“**左传|祭之地，地坟；与犬，犬毙；与小臣，小臣亦毙**”。有人劝申生向父亲申辩，申生说：“**左传|君非姬氏，居不安，食不饱**。”我若申辩，骊姬必然获罪，君老了，我不忍心。又劝他出走，他说背着弑父的罪名，谁会接纳我？十二月，申生在新城自缢。骊姬接着诬告公子重耳、夷吾同谋，二人分别逃回自己的封邑蒲和屈。',
    who: ['申生', '骊姬', '晋献公'] },
  { y: -655, zm: 1, t: '重耳奔狄', p: '蒲', m: '今山西隰县', ll: [110.94, 36.69], k: 'pol', refs: ['左传', '晋世家'],
    d: '晋献公派寺人披攻蒲，重耳说：“君父之命不校。”下令不许抵抗，“**左传|逾垣而走。披斩其袪，遂出奔翟**”。重耳的母亲是狄人，他在狄一住十二年，狐偃（子犯）、赵衰、颠颉、魏犨、胥臣等人追随左右。次年夷吾也从屈逃往梁国。同年冬，晋献公借道于虞以伐虢，宫之奇谏虞君“唇亡齿寒”，虞君不听，晋灭虢，回师途中顺手灭了虞。',
    who: ['晋文公', '寺人披', '狐偃', '赵衰', '晋献公', '胥臣'] },
  { y: -651, zm: 10, t: '里克之乱 · 荀息死节', p: '绛', m: '今山西翼城', ll: [111.55, 35.72], k: 'pol', refs: ['左传', '晋世家'],
    d: '九月，晋献公死，临终把奚齐托付给荀息。荀息说：“臣竭其股肱之力，加之以忠贞。”里克、丕郑要迎立重耳，十月在丧次杀了奚齐；荀息又立骊姬妹妹所生的卓子，十一月里克又在朝堂上杀了卓子，荀息随之自杀。《左传》引君子曰：“**左传|白圭之玷，尚可磨也；斯言之玷，不可为也**。荀息有焉。”同年夏，齐桓公会诸侯于葵丘，献公赴会途中折返，未能参加。',
    who: ['里克', '荀息', '晋献公', '骊姬'] },
  { y: -650, zm: 4, t: '晋惠公入立 · 杀里克', p: '绛', m: '今山西翼城', ll: [111.55, 35.72], k: 'pol', refs: ['左传', '晋世家'],
    d: '重耳不肯回国，夷吾许以河外五城贿赂秦穆公，又许里克汾阳之田，在秦、齐护送下回国即位，是为晋惠公。即位后他背弃了割地给秦的诺言，又要杀里克。里克说：“**左传|不有废也，君何以兴？欲加之罪，其无辞乎？臣闻命矣**。”伏剑而死。丕郑之子丕豹逃到秦国。',
    who: ['晋惠公', '里克', '秦穆公'] },
  { y: -647, mo: 10, t: '泛舟之役', p: '雍 → 绛', m: '今陕西凤翔 → 山西翼城', ll: [109.9, 35.0], k: 'pol', refs: ['左传', '秦本纪'],
    d: '晋国大饥，向秦求粮。丕豹劝秦穆公乘机伐晋。穆公问百里奚，百里奚说：“**左传|天灾流行，国家代有，救灾恤邻，道也。行道有福**。”穆公说：“其君是恶，其民何罪？”“**左传|秦于是乎输粟于晋，自雍及绛相继，命之曰泛舟之役**。”运粮船沿渭水、黄河、汾水一路相接，是先秦最著名的一次救灾漕运。',
    who: ['秦穆公', '百里奚', '晋惠公'] },
  { y: -645, mo: 10, t: '韩原之战', p: '韩原', m: '今陕西韩城（一说山西芮城、河津间）', ll: [110.45, 35.47], k: 'war', refs: ['左传', '秦本纪', '晋世家'],
    d: '次年秦国也遭饥荒，向晋求粮，晋惠公却拒绝了。秦穆公大怒，出兵伐晋，三败晋军，进至韩原。晋惠公不听庆郑的劝告，用郑国进贡的小驷驾车，结果“**左传|晋戎马还泞而止**”，陷在泥里。他呼救，庆郑说：“愎谏违卜，固败是求，又何逃焉？”扬长而去，晋惠公被秦军俘获。秦穆公夫人穆姬是晋惠公的姐姐，带着子女登台履薪，以死相求，穆公才答应放人。晋献出河东之地，以太子圉为人质，秦国“**左传|于是秦始征晋河东，置官司焉**”。',
    who: ['秦穆公', '晋惠公', '庆郑', '穆姬'] },
  { y: -644, mo: 6, t: '重耳去狄适齐', p: '五鹿', m: '今河南濮阳东南', ll: [115.4, 35.6], k: 'pol', refs: ['左传', '晋世家'],
    d: '晋惠公派寺人披到狄国行刺，重耳在狄住了十二年，只好离开，打算投奔齐桓公。经过卫国，卫文公不以礼相待。走到五鹿，向乡下人讨饭，“**左传|野人与之块，公子怒，欲鞭之。子犯曰：天赐也**”，土块是得到土地的吉兆，重耳于是叩头接受，装上车。到了齐国，齐桓公把宗女齐姜嫁给他，给了二十乘马，重耳在齐安居下来，不想再走。',
    who: ['晋文公', '狐偃', '齐桓公', '齐姜', '卫文公', '晋惠公', '寺人披'] },
  { y: -643, zm: 5, t: '子圉质秦 · 秦归河东', p: '河东', m: '今山西运城一带', ll: [110.99, 35.03], k: 'dip', refs: ['左传', '秦本纪'],
    d: '韩原之战后，晋惠公获释回国，答应以太子圉为人质。前 643 年夏，“**左传|晋大子圉为质于秦，秦归河东而妻之**”，秦穆公把两年前征收的河东之地还给晋国，又把宗女怀嬴嫁给子圉，想借此笼络晋国未来的国君。秦国仍保有黄河以西的河西之地，“**是时秦地东至河**”。五年后子圉听说父亲病重，不告而别逃回晋国，即晋怀公。',
    who: ['晋怀公', '秦穆公', '晋惠公', '怀嬴'] },
  { y: -643, zm: 10, t: '齐桓公卒 · 五公子争立', p: '临淄', m: '今山东淄博', ll: [118.3, 36.85], k: 'pol', refs: ['齐太公世家', '左传'],
    d: '管仲死前劝齐桓公远离易牙、竖刁、开方，桓公不听。十月桓公病死，五位公子各率党羽争位，易牙、竖刁杀群吏，立公子无亏，太子昭出奔宋国。诸公子互相攻打，没人顾得上收殓，“**桓公尸在床上六十七日，尸虫出于户**”。次年宋襄公率诸侯送太子昭回国，立为齐孝公。齐国霸业从此衰落，宋襄公借此想继齐称霸（详见《齐桓称霸》）。',
    who: ['齐桓公', '易牙', '竖刁', '齐孝公', '宋襄公'] },
  { y: -641, mo: 6, t: '秦灭梁、芮', p: '梁', m: '今陕西韩城', ll: [110.44, 35.48], k: 'war', refs: ['左传', '秦本纪', '晋世家'],
    d: '梁、芮是黄河西岸的小国，梁在今陕西韩城，芮在今大荔一带，晋惠公流亡时曾在梁国娶妻。“**左传|初，梁伯好土功，亟城而弗处，民罢而弗堪**”，于是谎称“某寇将至”，又挖沟围住宫室，说“秦将袭我”，“**左传|民惧而溃，秦遂取梁**”。《春秋》只写“梁亡”而不说谁灭的，《左传》解释为自取灭亡。《史记·秦本纪》系于秦穆公二十年：“**二十年，秦灭梁、芮**。”黄河西岸从此尽归秦国，秦、晋隔河相望。',
    who: ['秦穆公'] },
  { y: -639, zm: 7, t: '盂之会 · 宋襄公被执', p: '盂', m: '今河南睢县', ll: [115.07, 34.45], k: 'dip', refs: ['左传', '宋微子世家'],
    d: '宋襄公想继齐桓公做盟主，向楚国请求诸侯。公子目夷（子鱼）说：“小国争盟，祸也。宋其亡乎！”秋天诸侯在盂会盟，宋襄公不听目夷劝告，不带兵车赴会，结果楚成王当场把他拘捕，挟持他去攻打宋国。子鱼说：“**左传|祸其在此乎！君欲已甚，其何以堪之**？”冬天诸侯在薄会盟，楚才放了宋襄公。',
    who: ['宋襄公', '子鱼', '楚成王'] },
  { y: -638, zm: 11, t: '泓之战', p: '泓水', m: '今河南柘城北', ll: [115.3, 34.15], k: 'war', refs: ['左传', '宋微子世家'],
    d: '宋伐郑，楚伐宋救郑。十一月初一，两军战于泓水。宋军已经列好阵，楚军还在渡河。司马子鱼请求趁其半渡出击，宋襄公说不可；楚军过了河还没列好阵，子鱼又请击，襄公还是不许。等楚军列阵完毕才交战，宋军大败，“**左传|公伤股，门官歼焉**”。国人都怪罪襄公，襄公说：“**左传|君子不重伤，不禽二毛**。古之为军也，不以阻隘也。”子鱼说：“**左传|君未知战**。”次年宋襄公伤重而死。',
    who: ['宋襄公', '子鱼', '楚成王'] },
  { y: -637, mo: 3, t: '重耳过曹 · 曹共公观骈胁', p: '陶丘', m: '今山东定陶', ll: [115.57, 35.07], k: 'pol', refs: ['左传', '晋世家'],
    d: '在齐国住了五年，齐姜和子犯合谋把重耳灌醉，载上车离开齐国。到了曹国，曹共公听说重耳肋骨长成一片（骈胁），想看看，“**左传|浴，薄而观之**”。曹大夫僖负羁的妻子说：“**左传|吾观晋公子之从者，皆足以相国**。”劝丈夫及早结交，僖负羁便送去一盘饭，饭下藏着玉璧。重耳收下饭，退还了璧。此后经过宋国，宋襄公赠马二十乘；过郑国，郑文公不加礼遇。',
    who: ['晋文公', '曹共公', '僖负羁', '齐姜', '狐偃', '宋襄公', '郑文公'] },
  { y: -637, mo: 6, t: '楚成王飨重耳 · 退避三舍之约', p: '郢', m: '今湖北荆州', ll: [112.17, 30.43], k: 'pol', refs: ['左传', '晋世家'],
    d: '楚成王设宴款待重耳，问：“公子若反晋国，则何以报不穀？”重耳说，子女玉帛、羽毛齿革，楚国都有，“若以君之灵，得反晋国，**左传|晋、楚治兵，遇于中原，其辟君三舍**。若不获命，其左执鞭弭，右属櫜鞬，以与君周旋”。子玉请杀重耳，楚成王说晋公子志向远大而节俭，随从严肃而宽厚，忠诚而有能力，“天将兴之，谁能废之”，把他送去了秦国。',
    who: ['晋文公', '楚成王', '子玉'] },
  { y: -636, zm: 2, t: '重耳入晋 · 晋文公即位', p: '曲沃', m: '今山西闻喜', ll: [111.22, 35.36], k: 'pol', refs: ['左传', '晋世家', '秦本纪'],
    d: '晋太子圉从秦国逃回即位，是为晋怀公。秦穆公便转而支持重耳，嫁给他五个宗女，其中有怀公原来的妻子怀嬴。正月秦军护送重耳渡河，到了河边，子犯把玉璧交还重耳请求离去，重耳说：“**左传|所不与舅氏同心者，有如白水**！”把璧投入河中。二月重耳入曲沃，朝于武宫，即位为晋文公，派人在高梁杀了怀公。这年他已流亡十九年，六十二岁。',
    who: ['晋文公', '秦穆公', '怀嬴', '狐偃', '晋怀公'] },
  { y: -636, zm: 3, t: '吕郤之乱 · 寺人披告密', p: '王城', m: '今陕西大荔', ll: [109.95, 34.8], k: 'pol', refs: ['左传', '晋世家'],
    d: '惠公旧臣吕甥、郤芮怕受迫害，图谋焚烧宫室、杀死文公。当年斩重耳衣袖的寺人披来求见，文公派人斥责他。寺人披说：“**左传|君命无二，古之制也**。”齐桓公尚且置射钩之仇而用管仲，您难道要反其道而行？文公见了他，得知阴谋，悄悄赶到王城与秦穆公会面。三月宫室起火，吕、郤找不到文公，逃到河边，被秦穆公诱杀。',
    who: ['寺人披', '晋文公', '秦穆公'] },
  { y: -636, mo: 5, t: '介之推不言禄', p: '绵上', m: '今山西介休', ll: [111.9, 37.03], k: 'pol', refs: ['左传', '晋世家'],
    d: '文公赏赐随从流亡的功臣，介之推不求禄位，禄也没有落到他头上。他说献公九个儿子只剩国君一人，“**左传|天实置之，而二三子以为己力，不亦诬乎？窃人之财，犹谓之盗，况贪天之功以为己力乎**？”与母亲隐居而死。文公求之不得，“**左传|以绵上为之田，曰：以志吾过，且旌善人**”。后世寒食节的传说即附会于此。',
    who: ['介之推', '晋文公'] },
  { y: -636, zm: 10, t: '王子带之乱 · 天王出居于郑', p: '氾', m: '今河南襄城', ll: [113.48, 33.85], k: 'war', refs: ['左传', '周本纪'],
    d: '周襄王的异母弟王子带（甘昭公）与襄王之后隗氏私通，又勾结狄人攻王。秋天狄师伐周，大败周师，王子带占据王城。襄王出奔郑国，住在氾地，派人向鲁、晋、秦告难。《春秋》书“**左传|冬，天王出居于郑**”。',
    who: ['周襄王', '王子带'] },
  { y: -635, zm: 1, t: '卫灭邢', p: '夷仪', m: '今山东聊城西南', ll: [115.8, 36.3], k: 'war', refs: ['左传'],
    d: '邢是周公之后的姬姓国，前 659 年被狄人所逼，齐桓公率诸侯把它迁到夷仪。后来邢国反与狄人联合伐卫。前 635 年春卫人伐邢，卫大夫礼至兄弟事先投入邢国做官，随邢国正卿国子巡城时左右挟持，把他推下城墙摔死。正月“**左传|卫侯毁灭邢，同姓也，故名**”——《春秋》直书卫文公之名，是贬斥他灭了同姓之国。礼至还把这件事铸在铭文里夸耀。卫文公三个月后去世。',
    who: ['卫文公'] },
  { y: -635, zm: 4, t: '晋文公勤王 · 得南阳 · 伐原示信', p: '温 · 原', m: '今河南温县 · 济源', ll: [112.9, 35.0], k: 'war', refs: ['左传', '晋世家'],
    d: '秦穆公驻兵河上，准备送周襄王回京。狐偃对文公说：“**左传|求诸侯，莫如勤王**。”晋军抢先出兵，四月杀王子带于隰城，送襄王回王城。襄王赏赐晋文公阳樊、温、原、攒茅之田，晋国由此得到南阳之地，势力越过太行山。原地不服，文公围原，“**左传|命三日之粮。原不降，命去之**”。探子报告原人快投降了，军吏请求再等等，文公说：“**左传|信，国之宝也，民之所庇也**。”退兵一舍，原人反而投降。',
    who: ['晋文公', '狐偃', '周襄王', '王子带', '赵衰', '秦穆公'] },
  { y: -633, mo: 11, t: '楚围宋 · 晋作三军', p: '被庐', m: '今山西境内（地望不详）', ll: [111.6, 35.9], k: 'pol', refs: ['左传', '晋世家'],
    d: '楚成王会同陈、蔡、郑、许围宋。出征前老令尹子文让位于子玉，治兵时一早就结束，不杀一人，子玉却终日治兵，鞭七人、贯三人耳，国老都向子文道贺，只有年少的蔿贾说子玉“刚而无礼”，带兵超过三百乘必败。宋向晋告急。先轸说：“**左传|报施救患，取威定霸，于是乎在矣**。”晋文公在被庐大蒐，扩编为上中下三军，赵衰推荐郤縠将中军，说他“**左传|说礼、乐而敦诗、书**”。狐偃献策：楚国新得曹国，又与卫国新近通婚，若伐曹、卫，楚必来救，则齐、宋之围自解。',
    who: ['先轸', '郤縠', '晋文公', '赵衰', '狐偃', '楚成王', '子玉', '子文'] },
  { y: -632, zm: 3, t: '晋侵曹伐卫', p: '五鹿 · 陶丘', m: '今河南濮阳 · 山东定陶', ll: [115.4, 35.4], k: 'war', refs: ['左传', '晋世家'],
    d: '正月晋军借道卫国伐曹，卫国不许，晋军绕道渡河，取了卫地五鹿——正是当年重耳讨饭、野人给土块的地方。卫成公出居襄牛。三月晋军攻入曹都，俘虏曹共公，数落他当年观浴之辱。文公下令不许侵犯僖负羁之家，以报一饭之恩。晋把曹、卫的田地分给宋国，故意激怒楚国。',
    who: ['晋文公', '先轸', '曹共公', '僖负羁'] },
  { y: -632, zm: 4, t: '城濮之战', p: '城濮', m: '今山东鄄城西南', ll: [115.47, 35.55], k: 'war', refs: ['左传', '晋世家', '楚世家'],
    d: '楚成王不愿与晋决战，令子玉撤兵，子玉坚持请战。两军相遇，晋文公下令后退三舍（九十里），军吏不解，子犯说：“**左传|微楚之惠不及此，退三舍辟之，所以报也**。”四月己巳，两军战于城濮。晋下军佐胥臣“**左传|蒙马以虎皮，先犯陈、蔡**”，陈、蔡之兵溃逃，楚右师溃；栾枝在车后拖柴扬尘，假装败退，诱楚左师追击，先轸、郤溱以中军拦腰截击，楚左师又溃。子玉收中军撤退，未至大败。楚成王派人责问，子玉在连谷自杀。文公听到消息，喜形于色：“莫余毒也已！”',
    who: ['晋文公', '先轸', '子玉', '狐偃', '栾枝', '胥臣', '楚成王'] },
  { y: -632, zm: 5, t: '践土之盟 · 天王狩于河阳', p: '践土', m: '今河南原阳西南', ll: [113.83, 35.0], k: 'dip', refs: ['左传', '晋世家', '周本纪'],
    d: '战后晋文公在践土为周襄王修筑王宫，献楚俘车百乘、步卒千人。周王派“**左传|尹氏及王子虎、内史叔兴父策命晋侯为侯伯**”，赐大辂、彤弓、秬鬯、虎贲三百人，命他“**左传|敬服王命，以绥四国，纠逖王慝**”。五月诸侯盟于践土，晋文公成为霸主。冬天晋又会诸侯于温，召周王前来接受朝见。孔子认为“**左传|以臣召君，不可以训。故书曰：天王狩于河阳**”。城濮战前晋军占领的曹、卫两国，盟后归还：卫成公六月回国复位，曹共公也在冬天经晋文公的侍从侯獳进言而复位。',
    who: ['晋文公', '周襄王', '王子虎', '曹共公'] },
  { y: -630, zm: 9, t: '烛之武退秦师', p: '新郑', m: '今河南新郑', ll: [113.73, 34.4], k: 'dip', refs: ['左传', '郑世家'],
    d: '郑国曾对重耳无礼，又依附楚国，晋、秦联兵围郑。佚之狐推荐烛之武，烛之武推辞说：“**左传|臣之壮也，犹不如人；今老矣，无能为也已**。”郑文公认错，烛之武才答应，夜里用绳子缒出城去见秦穆公：“**左传|越国以鄙远，君知其难也，焉用亡郑以倍邻**？”郑亡对秦无益，“**左传|若舍郑以为东道主**”，秦使往来，郑可供其所需。秦穆公被说动，与郑结盟，留杞子等三人戍郑，撤军而去。子犯请求追击秦军，文公说：“**左传|因人之力而敝之，不仁；失其所与，不知；以乱易整，不武**。”也撤了兵。',
    who: ['烛之武', '秦穆公', '晋文公', '郑文公', '狐偃'] },
  { y: -627, zm: 2, t: '弦高犒师', p: '滑', m: '今河南偃师', ll: [112.78, 34.62], k: 'dip', refs: ['左传', '秦本纪'],
    d: '戍郑的杞子密报秦国：“郑人使我掌其北门之管，若潜师以来，国可得也。”晋文公去世不久，秦穆公不听蹇叔劝阻，派孟明视、西乞术、白乙丙东袭郑国。秦军经过周都北门，免胄下车而又跳上车的有三百乘，王孙满看了说：“**左传|秦师轻而无礼，必败**。”到了滑国，郑国商人弦高正要去周贩牛，遇到秦军，便冒充郑君的使者，“**左传|以乘韦先，牛十二犒师**”，同时派人急报郑国。郑穆公派人察看客馆，杞子等已在秣马厉兵，郑人下了逐客令，杞子等出逃。孟明视以为郑国已有防备，灭了滑国回师。',
    who: ['弦高', '孟明视', '王孙满', '秦穆公', '西乞术', '白乙丙', '蹇叔'] },
  { y: -627, zm: 4, t: '殽之战', p: '殽', m: '今河南三门峡陕州区东南', ll: [111.62, 34.6], k: 'war', refs: ['左传', '秦本纪', '晋世家'],
    d: '秦军出发时，蹇叔哭送：“**左传|孟子，吾见师之出，而不见其入也**！”又对从军的儿子说：“**左传|晋人御师必于殽**”，“必死是间，余收尔骨焉”。晋国正在为文公服丧，先轸主张截击，晋襄公“**左传|子墨衰绖**”，夏四月在殽山设伏，全歼秦军，俘获孟明视、西乞术、白乙丙。晋文公夫人文嬴（秦穆公之女）为三帅求情，晋襄公放走了他们。先轸知道后大怒：“武夫力而拘诸原，妇人暂而免诸国”，“**左传|不顾而唾**”。秦穆公素服郊迎，说“孤之过也”，仍用孟明。',
    who: ['孟明视', '蹇叔', '先轸', '晋襄公', '怀嬴', '秦穆公', '西乞术', '白乙丙'] },
  { y: -627, zm: 8, t: '箕之战 · 先轸免胄', p: '箕', m: '今山西太谷东（一说蒲县）', ll: [112.6, 37.42], k: 'war', refs: ['左传'],
    d: '狄人乘晋丧伐晋，攻到箕地。八月晋襄公在箕大败狄师，郤缺俘获白狄子。先轸自责当着国君的面唾地无礼，说：“**左传|匹夫逞志于君而无讨，敢不自讨乎**？”脱下头盔冲入狄阵战死。狄人送回他的首级，面色如生。',
    who: ['先轸', '晋襄公'] },
  { y: -626, zm: 10, t: '商臣弑成王', p: '郢', m: '今湖北荆州', ll: [112.17, 30.43], k: 'pol', refs: ['左传', '楚世家'],
    d: '楚成王立商臣为太子，后来又想改立王子职。商臣从姑母江芈口中证实了消息，师傅潘崇问他：能事奉王子职吗？能出逃吗？能行大事吗？商臣说能。十月，商臣率宫甲包围成王，“**左传|王请食熊蹯而死。弗听**”。成王自缢，商臣即位，是为楚穆王。熊掌难熟，成王想借此拖延待援，没能如愿。',
    who: ['楚成王', '楚穆王', '潘崇'] },
  { y: -624, zm: 5, t: '济河焚舟 · 封殽尸', p: '茅津', m: '今山西平陆 · 河南三门峡', ll: [111.2, 34.82], k: 'war', refs: ['左传', '秦本纪'],
    d: '殽之战后秦晋连年交兵，前 625 年孟明视在彭衙又败于晋。秦穆公仍然信任他。这一年“**左传|秦伯伐晋，济河焚舟**”，表示不胜不归，攻取王官和郊。晋人不敢出战，“**左传|遂自茅津济，封殽尸而还**”，在殽山为三年前战死的秦军将士收葬筑冢。',
    who: ['秦穆公', '孟明视'] },
  { y: -623, mo: 6, t: '秦霸西戎', p: '西戎', m: '今甘肃东部、宁夏南部', ll: [106.6, 35.6], k: 'war', refs: ['秦本纪'],
    d: '戎王派由余出使秦国，由余本是晋人，懂得秦语，秦穆公与他谈论治国，认为是贤人，用计离间他与戎王的关系，使由余归秦。秦穆公东进受阻于晋，便转而向西发展。“**三十七年，秦用由余谋伐戎王，益国十二，开地千里，遂霸西戎**。”周襄王派召公过赐秦穆公金鼓以示祝贺。',
    who: ['秦穆公', '由余', '周襄王'] },
  { y: -622, zm: 8, t: '楚灭六、蓼', p: '六', m: '今安徽六安', ll: [116.5, 31.75], k: 'war', refs: ['左传'],
    d: '六、蓼是皋陶、庭坚之后所封的偃姓小国，在今安徽六安、河南固始一带，介于楚与群舒、淮夷之间。前 622 年六人叛楚，亲附东夷，秋天楚成大心、仲归率军灭六，冬天公子燮又灭蓼。鲁国臧文仲听说后叹道：“**左传|皋陶、庭坚不祀忽诸。德之不建，民之无援，哀哉**！”楚国势力由此深入江淮之间。',
    who: ['臧文仲'] },
  { y: -621, mo: 4, t: '秦穆公卒 · 三良殉葬', p: '雍', m: '今陕西凤翔', ll: [107.4, 34.52], k: 'pol', refs: ['左传', '秦本纪'],
    d: '“**左传|秦伯任好卒，以子车氏之三子**奄息、仲行、鍼虎**左传|为殉，皆秦之良也。国人哀之，为之赋黄鸟**。”君子批评秦穆公死而弃民，说他不能做盟主是理所当然的。《史记》说从死者有一百七十七人。',
    who: ['秦穆公'] },
  { y: -620, zm: 4, t: '赵盾立灵公 · 令狐之战', p: '令狐', m: '今山西临猗', ll: [110.75, 35.15], k: 'war', refs: ['左传', '晋世家'],
    d: '前 621 年晋襄公去世，太子夷皋年幼，执政赵盾主张立年长的公子雍，派先蔑、士会去秦国迎接。襄公夫人穆嬴“**左传|日抱太子以啼于朝**”，又到赵盾家里叩头哭求。赵盾等人怕她，又怕国人逼迫，便背弃先蔑，立夷皋为君，即晋灵公，并发兵在令狐截击护送公子雍的秦军，大败秦师。先蔑、士会出奔秦国。',
    who: ['赵盾', '穆嬴', '晋灵公', '士会'] },
  { y: -611, mo: 7, t: '楚庄王一鸣惊人 · 灭庸', p: '上庸', m: '今湖北竹山', ll: [110.23, 32.22], k: 'war', refs: ['楚世家', '左传'],
    d: '楚庄王即位三年不出号令，日夜作乐，下令谏者死。伍举以隐语进谏：有鸟在阜，三年不飞不鸣。庄王说：“**三年不蜚，蜚将冲天；三年不鸣，鸣将惊人**。”此后又有苏从冒死直谏，庄王于是罢淫乐，诛数百人，进数百人，任伍举、苏从以政。这一年楚国大饥，戎人与庸国率群蛮、百濮叛楚，楚人一度想迁都。庄王坚持出兵，联合秦、巴，“**左传|楚人、秦人、巴人灭庸**”，楚国转危为安。',
    who: ['楚庄王', '伍举'] },
  { y: -607, zm: 9, t: '赵盾弑其君', p: '绛', m: '今山西翼城', ll: [111.55, 35.72], k: 'pol', refs: ['左传', '晋世家'],
    d: '“**左传|晋灵公不君：厚敛以雕墙；从台上弹人，而观其辟丸也**。”厨师煮熊掌不熟，就被杀死。赵盾屡次进谏，灵公派鉏麑去刺杀他。鉏麑清晨见赵盾已穿好朝服、坐着打盹，叹道：“**左传|贼民之主，不忠；弃君之命，不信**。”触槐而死。灵公又设宴埋伏甲士，赵盾靠车右提弥明和受过他一饭之恩的灵辄相救逃出。九月赵穿在桃园杀了灵公，赵盾还没出国境就回来了。太史董狐写道“**左传|赵盾弑其君**”，赵盾申辩，董狐说：“子为正卿，亡不越竟，反不讨贼，非子而谁？”孔子说：“**左传|董狐，古之良史也，书法不隐**。”',
    who: ['晋灵公', '赵盾', '赵穿', '董狐', '鉏麑'] },
  { y: -606, mo: 6, t: '楚庄王问鼎', p: '雒', m: '今河南洛阳', ll: [112.45, 34.68], k: 'dip', refs: ['左传', '楚世家', '周本纪'],
    d: '“**左传|楚子伐陆浑之戎，遂至于雒，观兵于周疆**。”周定王派王孙满慰劳楚师，“**左传|楚子问鼎之大小、轻重焉**”。王孙满回答：“**左传|在德不在鼎**。”夏有德时铸九鼎，桀昏德，鼎迁于商；商纣暴虐，鼎迁于周。“**左传|周德虽衰，天命未改。鼎之轻重，未可问也**。”楚庄王于是回师。',
    who: ['楚庄王', '王孙满', '周定王'] },
  { y: -605, mo: 5.5, t: '郑灵公染指', p: '新郑', m: '今河南新郑', ll: [113.73, 34.4], k: 'pol', refs: ['左传', '郑世家'],
    d: '“**左传|楚人献鼋于郑灵公。公子宋与子家将见。子公之食指动**”，他对子家说：以往我食指一动，必能尝到美味。进宫后果然见厨师在杀鼋，两人相视而笑。灵公问清缘故，分鼋羹给大夫们时偏偏不给子公。子公大怒，“**左传|染指于鼎，尝之而出**”。灵公要杀子公，子公便与子家先下手，夏天弑了灵公。“染指”和“食指大动”两个词都出自这里。',
    who: ['郑灵公', '公子宋', '子家'] },
  { y: -605, zm: 7, t: '若敖氏之乱', p: '皋浒', m: '今湖北襄阳西', ll: [112.0, 32.0], k: 'war', refs: ['左传', '楚世家'],
    d: '楚国令尹斗越椒（子越）出自强宗若敖氏，起兵攻楚庄王。秋七月两军战于皋浒，斗越椒射王，箭穿过车辕，射中鼓架，又一箭穿过车盖。楚军畏惧后退，庄王派人传话：先君得到三支神箭，斗越椒偷去两支，已经射完了。随后击鼓进兵，“**左传|遂灭若敖氏**”。楚国公族中势力最大的一支被清除，王权更加集中。',
    who: ['楚庄王', '斗越椒'] },
  { y: -601, zm: 6, t: '楚灭舒蓼 · 盟吴越', p: '舒', m: '今安徽庐江、舒城一带', ll: [117.1, 31.1], k: 'war', refs: ['左传'],
    d: '群舒是偃姓诸国，有舒、舒蓼、舒庸、舒鸠等，散布在今安徽庐江、舒城、桐城一带。前 601 年“**左传|楚为众舒叛故，伐舒蓼，灭之。楚子疆之，及滑汭，盟吴越而还**”，楚庄王亲自划定疆界，直到滑水弯曲处，又与吴、越会盟。这是吴、越两国较早见于《左传》的记载，楚国东境从此与吴相接。',
    who: ['楚庄王'] },
  { y: -599, zm: 5, t: '夏征舒弑陈灵公', p: '株林', m: '今河南柘城', ll: [115.3, 34.05], k: 'pol', refs: ['左传', '陈杞世家'],
    d: '“**左传|陈灵公与孔宁、仪行父通于夏姬，皆衷其衵服，以戏于朝**。”大夫泄冶进谏，被二人杀死。前 599 年五月，三人在夏氏家饮酒，灵公对仪行父说：“征舒似女。”仪行父答：“亦似君。”夏姬之子夏征舒忍无可忍，从马厩里射杀了灵公。孔宁、仪行父逃往楚国。',
    who: ['陈灵公', '夏姬', '夏征舒'] },
  { y: -598, zm: 10, t: '楚县陈 · 蹊田夺牛', p: '宛丘', m: '今河南淮阳', ll: [114.88, 33.73], k: 'war', refs: ['左传', '陈杞世家', '楚世家'],
    d: '冬天楚庄王以讨伐夏征舒为名进入陈国，车裂夏征舒，随即把陈国改设为楚的县。群臣都来祝贺，唯独申叔时不贺。他说：有人牵牛践踏别人的田，田主就把牛夺走，“**左传|牵牛以蹊人之田，而夺之牛**”，牵牛践田固然有罪，夺牛则罚得太重了。诸侯跟随楚国是为了讨伐罪人，如今却贪图陈国的土地，以后怎么号令诸侯？庄王说“善哉”，于是恢复陈国。',
    who: ['楚庄王', '申叔时', '夏征舒', '夏姬'] },
  { y: -597, zm: 6, t: '邲之战', p: '邲', m: '今河南荥阳东北', ll: [113.55, 34.88], k: 'war', refs: ['左传', '楚世家', '晋世家'],
    d: '春天楚庄王围郑十七天，攻破城墙，“**左传|郑伯肉袒牵羊以逆**”，楚庄王退兵三十里与郑讲和。晋荀林父率军救郑，到河边听说郑已降楚，想要回师，中军佐先縠不从，带着自己的部众渡河，全军只好跟进。孙叔敖、伍参主战，楚军先发制人，猛攻晋军。荀林父不知所措，在军中击鼓说：“先济者有赏。”“**左传|中军、下军争舟，舟中之指可掬也**。”晋军大败。有人劝楚庄王把晋军尸体堆成京观，庄王说：“**左传|夫文，止戈为武**。”只在河边祭祀先君、报告战功而还。晋军之中只有士会统领的上军事先设伏，全师而退。',
    who: ['楚庄王', '荀林父', '先縠', '孙叔敖', '郑襄公', '士会'] },
  { y: -595, zm: 9, t: '宋杀申舟 · 楚围宋', p: '商丘', m: '今河南商丘', ll: [115.65, 34.42], k: 'war', refs: ['左传', '楚世家'],
    d: '楚庄王派申舟出使齐国，故意命令他不向宋国借道。申舟早年曾在孟诸田猎时鞭打宋昭公的仆人，与宋结怨，自知此去必死，把儿子申犀托付给庄王才出发。经过宋国时，执政华元认为过境而不借道是把宋国当作楚国的边邑，与亡国无异，便杀了申舟。楚庄王闻讯，“**左传|投袂而起，屦及于窒皇，剑及于寝门之外，车及于蒲胥之市**”，当年九月出兵围宋。',
    who: ['申舟', '楚庄王', '华元'] },
  { y: -594, zm: 5, t: '华元夜入子反之床 · 宋楚平', p: '商丘', m: '今河南商丘', ll: [115.65, 34.42], k: 'war', refs: ['左传', '宋微子世家', '楚世家'],
    d: '前 595 年九月楚军围宋，宋国坚守九个月，粮尽，楚军也想撤兵。宋大夫华元夜里潜入楚营，登上楚将子反的床，叫醒他说：“**左传|敝邑易子而食，析骸以爨**。”但宁可亡国也不签城下之盟；若退兵三十里，唯命是听。子反恐惧，与他私下约定，报告庄王。五月楚军退兵三十里，宋楚讲和，盟辞是“**左传|我无尔诈，尔无我虞**”。',
    who: ['华元', '子反', '楚庄王'] },
  { y: -594, zm: 6, t: '晋灭赤狄潞氏', p: '潞', m: '今山西潞城', ll: [113.2, 36.33], k: 'war', refs: ['左传'],
    d: '潞子婴儿的夫人是晋景公的姐姐，潞国执政酆舒杀了她，又伤了潞子的眼睛。晋国诸大夫都说酆舒有三项过人的才能，不如等他死后再伐。伯宗说他有五大罪状，才能再多也无济于事。六月荀林父率军在曲梁打败赤狄，灭了潞氏。次年晋又灭赤狄甲氏、留吁、铎辰，太行山东西两侧的赤狄之地尽归晋国。',
    who: ['荀林父', '晋景公'] },
  { y: -594, zm: 8, t: '鲁初税亩', p: '曲阜', m: '今山东曲阜', ll: [116.99, 35.58], k: 'pol', refs: ['左传', '鲁周公世家'],
    d: '“**左传|初税亩，非礼也。谷出不过藉，以丰财也**。”此前鲁国只从公田收取收成（藉），这一年起无论公田私田，都按亩数征税。《左传》认为不合古礼，后世则把它看作承认土地私有、井田制瓦解的标志。',
    who: ['鲁宣公'] },
  { y: -589, zm: 6, t: '鞍之战', p: '鞍', m: '今山东济南西', ll: [116.9, 36.68], k: 'war', refs: ['左传', '齐太公世家', '晋世家'],
    d: '前 592 年晋国郤克出使齐国，他跛足，齐顷公让母亲萧同叔子在帷后观看，“**左传|郤子登，妇人笑于房**”，郤克发誓报复。这年齐伐鲁、卫，郤克率晋军救援，六月与齐战于鞍。齐顷公说：“**左传|余姑翦灭此而朝食**。”不给战马披甲就冲锋。郤克中箭，血流到鞋上，鼓声不绝，说：“**左传|余病矣**！”车夫解张说：“**左传|自始合，而矢贯余手及肘**”，我折断箭杆继续驾车，左轮都染红了，岂敢言病？齐军大败。韩厥追上齐顷公的车，车右逢丑父与齐侯换了位置，又让齐侯下车到华泉取水，齐侯乘机逃脱。晋人要求以萧同叔子为人质，齐国使臣宾媚人据理力争，最终议和。次年秋，郤克又与卫孙良夫伐廧咎如，“**左传|讨赤狄之余焉**”，太行山东麓的赤狄余部至此平定。',
    who: ['郤克', '齐顷公', '韩厥', '逢丑父'] },
  { y: -584, mo: 6, t: '巫臣通吴 · 吴始伐楚', p: '州来', m: '今安徽凤台', ll: [116.7, 32.7], k: 'war', refs: ['左传', '吴太伯世家'],
    d: '楚大夫申公巫臣阻止楚庄王和子反娶夏姬，自己却在前 589 年借出使之机带夏姬奔晋。子反和子重于是杀尽巫臣的族人，分其家产。巫臣写信说：“**左传|余必使尔罢于奔命以死**。”他请求出使吴国，带去战车，“**左传|教吴乘车，教之战陈，教之叛楚**”，又留下儿子做吴国的行人。吴王寿梦从此与中原通好，开始伐楚、伐巢、伐徐，攻入州来，“**左传|子重、子反于是乎一岁七奔命**”。',
    who: ['巫臣', '夏姬', '子反', '子重', '寿梦'] },
  { y: -583, mo: 6, t: '下宫之难 · 赵氏孤儿', p: '绛', m: '今山西翼城', ll: [111.6, 35.75], k: 'pol', refs: ['左传', '赵世家'],
    d: '《左传》记载：赵朔之妻赵庄姬与赵婴私通，赵婴被兄长赵同、赵括驱逐。庄姬怀恨，诬告赵同、赵括作乱，晋景公杀了二人。赵朔之子赵武随母亲养在宫中，韩厥对景公说：“**左传|成季之勋，宣孟之忠，而无后，为善者其惧矣**。”于是立赵武，归还赵氏田产。《史记》则讲了另一个故事：司寇屠岸贾诛灭赵氏，赵朔的门客公孙杵臼问友人程婴：“**立孤与死孰难**？”程婴说：“**死易，立孤难耳**。”二人以他人之子冒充孤儿，公孙杵臼赴死，程婴把赵武藏在山中抚养十五年，后由韩厥协助复立。《史记》系此事于晋景公三年（前 597 年），屠岸贾其人不见于《左传》，历来认为《史记》所记多出传闻。',
    who: ['赵武', '韩厥', '赵庄姬', '屠岸贾', '程婴', '公孙杵臼', '晋景公'] },
  { y: -581, zm: 6, t: '晋景公病入膏肓', p: '新田', m: '今山西侯马', ll: [111.37, 35.62], k: 'pol', refs: ['左传'],
    d: '前 585 年晋迁都新田。这年晋景公梦见厉鬼，病重，向秦国求医，秦伯派医缓前来。医生未到，景公梦见病魔化作两个小孩，一个说：良医来了，我们往哪里逃？另一个说：“**左传|居肓之上，膏之下，若我何**？”医缓到后果然说：“**左传|疾不可为也。在肓之上，膏之下，攻之不可，达之不及，药不至焉，不可为也**。”六月新麦熟了，景公召来曾预言他吃不到新麦的桑田巫，把新麦给他看后杀了他，“**左传|将食，张，如厕，陷而卒**”。',
    who: ['晋景公', '医缓'] },
  { y: -578, zm: 5, t: '吕相绝秦 · 麻隧之战', p: '麻隧', m: '今陕西泾阳北', ll: [108.85, 34.6], k: 'war', refs: ['左传', '秦本纪'],
    d: '秦桓公与晋厉公在令狐约盟，回国后就背约联合狄、楚伐晋。四月晋派吕相出使秦国，宣读绝交书：“**左传|昔逮我献公及穆公相好，戮力同心，申之以盟誓，重之以昏姻**。”历数秦国从殽之战以来的种种背信，文辞铿锵，是《左传》中著名的外交辞令。五月晋率齐、宋、卫、鲁、郑、曹、邾、滕八国之师伐秦，在麻隧大败秦军，渡过泾水，到侯丽而还。',
    who: ['吕相', '晋厉公', '秦桓公'] },
  { y: -575, zm: 6, t: '鄢陵之战', p: '鄢陵', m: '今河南鄢陵', ll: [114.18, 34.1], k: 'war', refs: ['左传', '晋世家', '楚世家'],
    d: '郑国叛晋附楚，晋厉公率军伐郑，楚共王亲自来救。六月晦日，楚军清晨逼近晋营布阵，晋军无处列阵，范匄说：“**左传|塞井夷灶，陈于军中，而疏行首**。”楚共王登巢车观望晋军，由晋国叛臣伯州犁讲解；晋这边则有楚国叛臣苗贲皇献策，建议先击楚左右军精锐。交战中晋将吕锜射中楚共王的眼睛，共王召来神射手养由基，只给两支箭，养由基一箭射死吕锜。楚军败退，共王召子反商议再战，“**左传|谷阳竖献饮于子反，子反醉而不能见**”。共王叹道天要败楚，连夜撤兵，子反自杀。战前一年冬，许灵公畏惧郑国逼迫，请迁于楚，“**左传|楚公子申迁许于叶**”，许国故地入郑；楚又以汝阴之田贿赂郑国，郑遂叛晋。',
    who: ['晋厉公', '楚共王', '子反', '吕锜', '养由基', '栾书', '范文子', '苗贲皇', '郤至'] },
  { y: -573, zm: 1, t: '晋厉公被弑 · 悼公即位', p: '新田', m: '今山西侯马', ll: [111.37, 35.62], k: 'pol', refs: ['左传', '晋世家'],
    d: '晋厉公在鄢陵大胜后骄纵，宠信胥童等人，前 574 年冬杀郤锜、郤犨、郤至“三郤”，又放过了栾书、中行偃。前 573 年正月，栾书、中行偃趁厉公游于匠丽氏，把他囚禁杀死，从周迎回年仅十四岁的公子周。公子周在清原对大夫们说：“**左传|抑人之求君，使出命也，立而不从，将安用君**？”众人皆表示听命，于是即位，是为晋悼公。他选贤任能，宽缓民力，晋国再度振兴。',
    who: ['晋厉公', '栾书', '中行偃', '晋悼公', '郤至'] },
  { y: -569, mo: 6, t: '魏绛和戎', p: '新田', m: '今山西侯马', ll: [111.4, 35.66], k: 'dip', refs: ['左传', '晋世家'],
    d: '山戎无终子嘉父派孟乐入晋，献虎豹之皮，请求与诸戎讲和。晋悼公说：“戎狄无亲而贪，不若伐之。”魏绛说：“**左传|和戎有五利焉**：**左传|戎狄荐居，贵货易土，土可贾焉**”，一也；边境安宁，二也；戎狄事晋，诸侯震恐，三也；不劳师旅，四也；以德服人，五也。悼公大悦，派魏绛与诸戎盟誓。此前一年鸡泽之会，魏绛还曾依军法斩了悼公之弟杨干的车夫，悼公不但不怪罪，反而更加器重他。',
    who: ['魏绛', '晋悼公'] },
  { y: -570, zm: 2, t: '子重伐吴 · 鸠兹之役', p: '鸠兹', m: '今安徽芜湖', ll: [118.38, 31.33], k: 'war', refs: ['左传'],
    d: '吴王寿梦与中原通好后屡次侵楚。前 570 年春，“**左传|楚子重伐吴，为简之师，克鸠兹，至于衡山**”，又派邓廖率组甲三百、被练三千深入吴境，被吴人截击，邓廖被俘，逃回的只有组甲八十、被练三百。子重回国饮酒庆功才三天，吴人反攻，夺取楚国的驾邑。君子说子重这一仗得不偿失，“**左传|楚人以是咎子重。子重病之，遂遇心病而卒**”。',
    who: ['子重', '寿梦'] },
  { y: -567, zm: 11, t: '齐灭莱', p: '莱', m: '今山东龙口', ll: [120.5, 37.62], k: 'war', refs: ['左传', '齐太公世家'],
    d: '莱是东夷古国，与齐国为邻，屡被齐伐。前 567 年齐灵公派晏弱攻莱，围城一年多，“**左传|十一月丙辰，而灭之。迁莱于郳**”。齐国疆土由此扩展到胶东半岛，东临大海。',
    who: ['齐灵公', '晏弱'] },
  { y: -563, zm: 4, t: '偪阳之战 · 叔梁纥抉门', p: '偪阳', m: '今山东枣庄峄城区', ll: [117.6, 34.77], k: 'war', refs: ['左传'],
    d: '晋荀偃、士匄要攻取偪阳，送给宋国向戌作封邑。诸侯之师围城，偪阳人打开城门，等诸侯士兵进入后放下悬门，想把他们关在里面。“**左传|县门发，郰人纥抉之以出门者**”——鲁国郰邑大夫叔梁纥用双手托住了沉重的悬门，让入城的士兵退了出来。叔梁纥就是孔子的父亲。偪阳最终被攻灭，宋人推辞不受，晋把它交给宋公。',
    who: ['叔梁纥', '中行偃', '向戌'] },
  { y: -562, zm: 9, t: '萧鱼之会 · 晋悼公复霸', p: '萧鱼', m: '今河南原阳东', ll: [114.0, 35.05], k: 'dip', refs: ['左传', '晋世家'],
    d: '晋悼公采纳知罃的“三分四军”之策，轮番出兵伐郑，楚国疲于奔命、无力相争，郑国终于彻底服晋。九月诸侯会于萧鱼，郑国送来乐师、钟磬和女乐，悼公把一半赐给魏绛：“**左传|子教寡人和诸戎狄，以正诸华。八年之中，九合诸侯，如乐之和，无所不谐**。”魏绛辞谢，劝悼公“**左传|居安思危**”，思则有备，有备无患。',
    who: ['晋悼公', '魏绛', '荀罃'] },
  { y: -559, zm: 4, t: '迁延之役', p: '棫林', m: '今陕西泾阳', ll: [108.7, 34.6], k: 'war', refs: ['左传'],
    d: '晋率诸侯伐秦，渡过泾水到达棫林，秦军不肯讲和。中军元帅荀偃下令：“**左传|鸡鸣而驾，塞井夷灶，唯余马首是瞻**。”下军将栾黡说：“**左传|晋国之命，未是有也。余马首欲东**。”掉头就走，下军随之东归。荀偃只好撤军，晋人称之为“迁延之役”。“马首是瞻”一词出自这里。',
    who: ['中行偃', '栾黡'] },
  { y: -555, zm: 10, t: '平阴之战', p: '平阴', m: '今山东平阴', ll: [116.45, 36.28], k: 'war', refs: ['左传', '齐太公世家'],
    d: '齐灵公屡次侵鲁，晋平公会同十二国诸侯伐齐，十月战于平阴。晋人遍插旌旗、车拖柴草，扬尘造势，齐灵公登巫山望见，以为晋军人多，连夜逃走。师旷说：“**左传|鸟乌之声乐，齐师其遁**。”邢伯说有班马之声，叔向也说：“**左传|城上有乌，齐师其遁**。”诸侯之师长驱直入，焚烧临淄外郭，一直打到潍水、沂水。',
    who: ['中行偃', '齐灵公', '师旷', '叔向'] },
  { y: -550, mo: 5, t: '栾盈之乱', p: '曲沃', m: '今山西闻喜', ll: [111.22, 35.36], k: 'war', refs: ['左传', '晋世家'],
    d: '栾黡之子栾盈好施，士多归附，执政范宣子忌惮他。前 552 年栾盈被逐，出奔楚国，又转往齐国。前 550 年齐庄公把他藏在陪嫁的车中送回曲沃，栾盈率曲沃之甲白天攻入绛都。范宣子挟晋平公避入固宫，栾氏攻宫失败，退回曲沃，晋军围攻，栾盈被杀，栾氏族灭。齐庄公随后亲自伐晋，攻取朝歌，登太行而还。',
    who: ['栾盈', '范宣子', '齐庄公'] },
  { y: -548, zm: 5, t: '崔杼弑其君', p: '临淄', m: '今山东淄博', ll: [118.3, 36.85], k: 'pol', refs: ['左传', '齐太公世家', '管晏列传'],
    d: '齐庄公与崔杼之妻棠姜私通，崔杼称病不朝，庄公来探视时又去找棠姜，被崔杼的家兵围攻杀死。晏婴站在崔家门外，说：“**左传|君民者，岂以陵民？社稷是主**。”国君为社稷而死，臣下才跟着死；若是为私事而死，“**左传|非其私暱，谁敢任之**”。他进门枕尸而哭，起身三踊而出。崔杼立庄公之弟为景公，自任右相。“**左传|大史书曰：崔杼弑其君。崔子杀之。其弟嗣书，而死者二人。其弟又书，乃舍之**。”南史氏听说太史都死了，执简前往，得知已经书写成功，才回去。',
    who: ['崔杼', '齐庄公', '晏婴', '棠姜'] },
  { y: -546, zm: 7, t: '弭兵之会', p: '宋西门外', m: '今河南商丘', ll: [115.6, 34.38], k: 'dip', refs: ['左传', '宋微子世家'],
    d: '“**左传|宋向戌善于赵文子，又善于令尹子木，欲弭诸侯之兵以为名**。”他奔走晋、楚、齐、秦，各国都同意了。七月十四国大夫在宋国西门外会盟，约定“**左传|晋、楚之从交相见也**”，即晋、楚的附属国要同时朝见两国。盟会时楚人衣内穿甲，又为谁先歃血争执，叔向劝赵武让楚先歃。此后四十余年间晋楚间再无大战，中原诸侯稍得喘息，争霸的重心转向东南的吴、越（续见《吴越争霸》）。鲁国执政季武子以公命要叔孙豹降格，比照邾、滕小国参盟，叔孙豹说鲁是列国，宋、卫才是我们的匹敌，坚持不从。',
    who: ['向戌', '赵武', '屈建', '叔向', '叔孙豹'] },
];
EVENTS.forEach(e => { if (e.zm) { e.cal = zhouMonth(e.y, e.zm); e.mo = Math.max(1, e.zm - 1); } });

// [名, 势力, 字, 生卒, 简介]
const PEOPLE_RAW = [
  // 晋
  ['晋献公', 'jin', '', '?–前651', '名诡诸，晋武公之子。在位时“并国十七，服国三十八”，假道于虞以伐虢，灭虢、虞。晚年宠骊姬，逼死太子申生，逐重耳、夷吾，晋国因此内乱二十年。'],
  ['骊姬', 'jin', '', '?–前651', '骊戎之女，晋献公伐骊戎所得，与妹妹一同被立为夫人，生奚齐。她得宠后想立奚齐为太子，先劝献公让太子申生、公子重耳、夷吾出居曲沃、蒲、屈等边邑，又说申生梦见齐姜，让他去曲沃祭祀，把送回的胙肉放毒，诬陷申生弑父。申生自缢，重耳、夷吾出奔。献公死后，奚齐、卓子相继被里克所杀，骊姬也被鞭杀。'],
  ['申生', 'jin', '', '?–前656', '晋献公太子，屡立战功。被骊姬以毒胙陷害，不肯申辩也不肯出走，自缢于新城，谥恭世子。'],
  ['晋文公', 'jin', '', '前697–前628', '名重耳，晋献公之子，母为狄女狐姬。骊姬之乱时被父亲派寺人披追杀，斩断衣袖逃到狄国，此后流亡狄、卫、齐、曹、宋、郑、楚、秦十九年，在卫乞食被野人给以土块，在齐安于娶妻，被齐姜与狐偃灌醉送走。六十二岁在秦穆公护送下回国即位，“**左传|晋公子广而俭，文而有礼**”。他勤王平王子带之乱，得南阳之地；城濮之战退避三舍，大败楚军，践土会盟受周王策命为侯伯，成为继齐桓公之后的霸主。在位九年。'],
  ['晋惠公', 'jin', '', '?–前637', '名夷吾，晋献公之子，重耳之弟。骊姬之乱时出奔梁国。献公死后，他以割河西五城为条件求秦穆公支持，回国即位，即位后背弃割地之约，又逼杀拥立他的里克，与群臣离心。晋国饥荒时秦国泛舟输粟，次年秦饥，他却拒绝援助。前 645 年秦伐晋，韩原之战他陷入泥中，被秦俘获，靠姐姐穆姬以死相求才获释，以太子圉为质于秦。在位十四年。'],
  ['晋怀公', 'jin', '', '?–前636', '名圉，晋惠公之子，韩原之战后入秦为质，秦穆公把女儿怀嬴嫁给他。前 638 年听说父亲病重，他怕君位被别人夺去，不告而别私自逃回晋国，次年即位。他下令随重耳流亡的人限期回国，不回者罪及其家，杀了狐偃、狐毛的父亲狐突。重耳在秦国支持下回国，他出奔高梁，被重耳派人杀死，在位仅数月。'],
  ['晋襄公', 'jin', '', '?–前621', '名欢，晋文公之子。即位之初文公尚未下葬，秦军越境袭郑，他采纳先轸之策，把丧服染黑，墨绖从戎，在殽山伏击秦军，全歼秦师，俘获孟明视等三帅，又听母亲文嬴之言放归三帅。同年在箕大败狄人，又伐卫、伐许，打败楚的盟国，守住了文公的霸业。在位七年，死时太子夷皋年幼，引出立君之争。'],
  ['晋灵公', 'jin', '', '?–前607', '名夷皋，晋襄公之子，幼年即位，执政赵盾一度想改立长君，因母亲穆嬴抱着他在朝堂哭泣才得立。长大后荒淫残暴，厚敛以雕墙，从台上用弹弓弹人看行人躲避取乐，厨师炖熊掌不熟就杀死，把尸体放在畚箕中让宫女抬过朝堂。赵盾屡谏，他先派鉏麑行刺，又设宴伏甲、纵獒犬追杀，前 607 年被赵盾族弟赵穿杀于桃园。'],
  ['晋景公', 'jin', '', '?–前581', '名獳，晋成公之子。前 597 年邲之战晋军败于楚，此后他整军经武，前 594 年派荀林父灭赤狄潞氏，次年又灭甲氏、留吁。前 589 年鞍之战郤克大败齐国，迫齐归还鲁卫之地。他迁都新田，又派巫臣出使吴国，联吴制楚。下宫之难后诛灭赵氏，后经韩厥进言恢复赵武的田邑。晚年病重，梦见二竖子藏于膏之下、肓之上，医缓说病不可为，“病入膏肓”的典故即出于他，后坠入粪坑而死。'],
  ['晋厉公', 'jin', '', '?–前573', '名寿曼，晋景公之子。前 578 年派吕相出使秦国宣读绝交书，率诸侯之师在麻隧大败秦军；前 575 年鄢陵之战大败楚军，楚共王伤目，晋国声威复振。此后他骄奢，想去掉群大夫，改立左右亲信，杀郤锜、郤犨、郤至三郤，又放过栾书、中行偃。前 573 年在出游匠丽氏时被栾书、中行偃囚禁杀死，只以车一乘葬于翼东门外。'],
  ['晋悼公', 'jin', '', '前586–前558', '名周，晋襄公曾孙，自幼在周事单襄公，十四岁被栾书等从京师迎回即位。他即位后选贤任能，以魏绛、知罃、韩厥等为卿，抚恤国人，修政安民。采纳魏绛“和戎五利”之策，与诸戎结盟，安定北方；用知罃“三分四军”轮番出击之策疲楚，三驾而楚不能与争，郑国服晋，“**左传|八年之中，九合诸侯**”，晋国复霸。在位十五年，二十九岁去世。'],
  ['狐偃', 'jin', '子犯', '?–前622', '字子犯，狐突之子，重耳的舅舅，随重耳流亡十九年，智谋第一。重耳在卫国乞食被野人给以土块，他说“天赐也”；在齐国安于娶妻，他与齐姜合谋把重耳灌醉送走。回国前在河边把玉璧还给重耳请辞，重耳以河为誓。他劝文公勤王以求诸侯，伐曹卫以引楚北上，城濮之战前主张退避三舍以报楚恩、又以曲直激励士气，是晋文公霸业的主要谋划者。'],
  ['赵衰', 'jin', '子余', '?–前622', '字子余，谥成季，赵夙之弟，随重耳流亡十九年，以文辞见长，在狄国娶狄女叔隗，生赵盾。重耳在秦穆公宴上赋诗，由他相礼应对。文公回国后，他屡次推让卿位，在被庐之蒐时举荐郤縠为中军将，又让位于栾枝、先轸、胥臣，《左传》称其“让，德之基也”。后任中军佐，与狐偃同年去世。赵氏由此兴起。'],
  ['先轸', 'jin', '', '?–前627', '晋国中军元帅，原为下军佐，郤縠死后被破格提升。城濮之战前他主张执曹君、分曹卫之田以畀宋，激怒楚国，又私许复曹卫以离间其与楚的关系，引诱子玉决战，是城濮之战的主要谋划者。殽之战力主截击秦军，全歼秦师。文嬴劝襄公放走秦国三帅后，他当着襄公的面唾地痛骂，自责无礼，同年在箕之战中免胄冲入狄阵战死，狄人归还其首，面如生。'],
  ['郤縠', 'jin', '', '?–前632', '晋国大夫。前 633 年晋文公在被庐大蒐，作三军，谋元帅，赵衰推荐他，说他“**左传|说礼、乐而敦诗、书**”，诗书是义之府，礼乐是德之则，德义是利之本，于是任为中军将，郤溱为佐。次年正月他率晋军南下，渡河伐卫，攻取五鹿，在城濮之战前病逝，先轸由下军佐升任中军将。'],
  ['栾枝', 'jin', '', '?–?', '晋国下军将，谥贞子。城濮之战中，他让部下在战车后拖着柴枝扬起尘土，伪装败退，诱楚左师追击，原轸、郤溱以中军公族横击之，楚左师溃败。战前晋文公梦见与楚王搏斗，被楚王伏在身上吸脑，心中害怕，子犯以“我得天，楚伏其罪”解梦。他也参与了殽之战。'],
  ['胥臣', 'jin', '', '?–?', '晋国大夫，又称臼季、司空季子，随重耳流亡。城濮之战中任下军佐，以虎皮蒙在战马身上，率先冲击楚右师中的陈、蔡之兵，陈蔡之兵奔逃，楚右师溃败。他出使途经冀地，看见郤缺在田中锄草，其妻送饭，相敬如宾，于是把郤缺推荐给晋文公，郤缺后来成为晋国中军元帅。'],
  ['介之推', 'jin', '', '?–?', '随重耳流亡的侍从，传说在重耳饥困时曾割股肉以食之。文公回国后赏赐从亡者，他不言禄，禄亦弗及。他说献公之子九人，唯君在矣，是天置之，而二三子以为己力，“**左传|贪天之功以为己力**”，不亦诬乎，下义其罪，上赏其奸，难与处矣，于是与母亲隐居绵上而死。文公求之不得，以绵上之田为其祭田，说“以志吾过，且旌善人”。后世传说寒食节即为纪念他。'],
  ['寺人披', 'jin', '', '?–?', '晋国宦官，又称勃鞮。骊姬之乱时奉献公之命到蒲城追杀重耳，重耳翻墙逃走，被他斩断衣袖；后又奉惠公之命到狄国追杀重耳。文公即位后，吕甥、郤芮怕被追究，想焚烧宫室杀文公，他求见文公告发，文公派人责问他斩袪之事，他说除君之恶，唯力是视，奉命无二。文公于是见他，得知阴谋，潜出秦国，吕郤之谋不成。'],
  ['里克', 'jin', '', '?–前650', '晋国大夫，曾任中军将。献公宠骊姬，欲废太子申生，他保持中立。献公死后，他先在丧次杀了奚齐，荀息又立卓子，他再在朝堂杀卓子，并杀荀息，派人迎立在梁国的夷吾。夷吾即位为惠公后，以他杀二君一大夫为由，说“为子君者，不亦难乎”，逼他自杀，他说“欲加之罪，其无辞乎”，伏剑而死。'],
  ['荀息', 'jin', '', '?–前651', '晋国大夫，献公托孤之臣，先后立奚齐、卓子，二人被杀后自杀，以践诺言。'],
  ['庆郑', 'jin', '', '?–前645', '晋国大夫，屡次劝谏晋惠公履行割地之约、在秦饥时输粟，惠公都不听。前 645 年韩原之战，惠公不用他为车右，战马陷入泥中，惠公呼他相救，他说愎谏违卜，固败是求，又何逃焉，转而去救韩简，结果惠公被秦俘获。惠公归国后，有人劝他出逃，他说“君而不报，罪也”，等惠公回来后被杀。'],
  ['赵盾', 'jin', '', '?–前601', '赵衰之子，母为狄女叔隗，谥宣子。前 621 年任中军元帅，执政晋国二十年，修订法令，整顿刑狱。襄公死后他想立长君，因太子之母穆嬴抱太子在朝堂哭泣而改立灵公。灵公荒淫，他屡谏，灵公先派鉏麑行刺，又设宴伏甲、纵獒追杀，他出奔未出境，族弟赵穿弑灵公，他回来迎立成公。太史董狐书“赵盾弑其君”，孔子说他是“古之良大夫也，为法受恶，惜也，越竟乃免”。'],
  ['士会', 'jin', '', '?–?', '名会，字季，又称随会、范武子，晋国大夫，晋文公时为车右。前 620 年他奉命赴秦迎立公子雍，赵盾变卦改立灵公，他留在秦国，屡为秦出谋，晋人设计把他诱回。邲之战时他统领上军，事先设伏，全军而退；后灭赤狄甲氏、留吁，受命为中军将兼太傅，修订法度，晋国的盗贼逃奔秦国。他是范氏的始祖，晋国称其“举不失德，赏不失劳”。'],
  ['赵穿', 'jin', '', '?–?', '赵盾的族弟，晋襄公之婿。前 615 年河曲之战中，他不听命令擅自出击秦军，赵盾为救他只得全军出战。前 607 年晋灵公追杀赵盾，赵盾出奔，尚未出境，他在桃园攻杀灵公，迎回赵盾，赵盾派他到周迎立公子黑臀，是为晋成公。董狐以赵盾“亡不越竟，反不讨贼”书其弑君。'],
  ['董狐', 'jin', '', '?–?', '晋国太史。晋灵公被赵穿所杀，他在史册上书“**左传|赵盾弑其君**”，并在朝堂上公示。赵盾说不是我，他说你身为正卿，亡不越境，回来又不讨伐弑君之贼，不是你又是谁？孔子称赞他“古之良史也，书法不隐”。“董狐之笔”从此成为史官秉笔直书、不避权贵的代称，文天祥《正气歌》有“在晋董狐笔”之句。'],
  ['鉏麑', 'jin', '', '?–前607', '晋国力士，晋灵公派他去刺杀屡次进谏的赵盾。他清晨前往，见赵盾寝门已开，赵盾已穿好朝服准备上朝，时间尚早，坐着闭目养神。他退出来叹道：“不忘恭敬，民之主也。贼民之主，不忠；弃君之命，不信。有一于此，不如死也。”于是一头撞在赵盾庭院的槐树上而死。'],
  ['穆嬴', 'jin', '', '?–?', '秦国之女，晋襄公夫人，晋灵公之母。襄公死后，太子夷皋年幼，执政赵盾因晋国多难，想立在秦国的公子雍为长君，派先蔑、士会去迎接。穆嬴每天抱着太子在朝堂上哭泣，又到赵盾家中顿首，说先君把此子托付于你，你若背弃，是何道理。赵盾与诸大夫都怕她，又怕国人逼迫，于是背弃迎公子雍之约，改立夷皋为君，并在令狐打败护送公子雍的秦军。'],
  ['荀林父', 'jin', '', '?–?', '晋国中军元帅，谥桓子。晋文公作三行以御狄，他将中行，其后代因此称中行氏。前 597 年楚围郑，他率晋军救郑，郑已降楚，他主张退兵，中军佐先縠擅自渡河，他只得全军跟进，邲之战中统军无方，晋军大败，争舟渡河，舟中之指可掬。他请死，晋景公听士贞子之谏，复其位。前 594 年他率军灭赤狄潞氏，将功补过，景公赏他狄臣千室。'],
  ['先縠', 'jin', '', '?–前596', '晋国中军佐，先轸之孙，又称彘子，刚愎自用。前 597 年晋救郑，听说郑已与楚讲和，中军元帅荀林父主张退兵，他说“成师以出，闻敌彊而退，非夫也”，擅自率中军佐所属渡河，晋军被迫全军渡河，在邲之战中大败。次年他招引赤狄伐晋，晋人归罪于他，杀先縠，先氏灭族。'],
  ['郤克', 'jin', '', '?–前587', '郤缺之子，谥献子，跛足。前 592 年出使齐国，齐顷公让母亲萧同叔子在帷后观看，萧同叔子笑他跛足，他发誓“所不此报，无能涉河”。前 589 年任中军元帅，率晋军救鲁、卫，在鞍之战大败齐军，他被箭射伤，“**左传|流血及屦，未绝鼓音**”，说“余病矣”，御者解张说自己手肘被箭贯穿也不敢说病，他坚持击鼓，晋军乘胜追击，齐军大败。'],
  ['韩厥', 'jin', '', '?–?', '谥献子，韩氏之祖，自幼被赵盾收养。鞍之战中任司马，追击齐顷公，齐顷公与车右逢丑父换了位置，他俘虏了假的齐侯，真的顷公借取水之名逃脱。他在晋景公面前直言进谏，赵氏遭下宫之难后，力保赵武，说成季、宣孟之忠，而无后，为善者其惧矣，景公于是复立赵武。悼公时任中军元帅，为人忠正，以公族大夫之位让于无忌。'],
  ['赵庄姬', 'jin', '', '?–?', '晋成公之女，赵朔之妻，赵武之母。赵朔死后，她与赵婴齐私通，赵同、赵括把赵婴齐放逐到齐国。前 583 年她向晋景公诬告赵同、赵括将要作乱，栾氏、郤氏为她作证，晋景公杀赵同、赵括，灭其族，史称下宫之难；赵武跟着母亲住在宫中，得以保全。（《史记·赵世家》所记屠岸贾灭赵、程婴救孤的故事与此不同。）'],
  ['赵武', 'jin', '', '前598–前541', '谥文子，赵朔之子，母为晋成公之女赵庄姬，即“赵氏孤儿”。下宫之难时随母住在宫中得以保全，后经韩厥进言，晋景公恢复其田邑。他少年时冠见诸卿，范文子、韩厥等都予以告诫。晋平公时任中军元帅，执政晋国，为人谦恭，主张以德服人，前 546 年与楚令尹屈建共同主持弭兵之会，晋楚之间此后四十余年没有大战。'],
  ['屠岸贾', 'jin', '', '?–?', '据《史记·赵世家》为晋灵公时的宠臣，晋景公时任司寇，以赵盾弑灵公为罪名，不请示国君，擅自与诸将攻赵氏于下宫，杀赵朔、赵同、赵括、赵婴齐，灭其族。赵朔的遗腹子赵武被程婴、公孙杵臼救下，十五年后韩厥言于景公，赵武与韩厥攻屠岸贾，灭其族。其人不见于《左传》，元杂剧《赵氏孤儿》即据此演绎。'],
  ['程婴', 'jin', '', '?–?', '据《史记·赵世家》为赵朔之友。屠岸贾灭赵氏时，赵朔之妻庄姬怀有身孕，藏于宫中生下赵武。他与赵朔门客公孙杵臼商议，由公孙杵臼带着他人之子藏匿山中，他假装出首告发，屠岸贾杀公孙杵臼与假孤儿，他则带着真孤儿藏于山中十五年。赵武冠礼成人、复立赵氏后，他说要下报赵宣孟与公孙杵臼，自杀而死。'],
  ['公孙杵臼', 'jin', '', '?–?', '据《史记·赵世家》为赵朔的门客。屠岸贾灭赵氏后搜捕赵氏孤儿，他问程婴立孤与死孰难，程婴说死易立孤难，他说你来做难的，我做容易的，于是用他人的婴儿冒充赵氏孤儿，裹以文葆，藏匿山中，由程婴出首告发。屠岸贾派兵追杀，他抱着假孤儿大骂程婴卖友，与假孤儿一同被杀，以掩护程婴和真孤儿。'],
  ['医缓', 'qin', '', '?–?', '秦国名医。前 581 年晋景公病重，向秦国求医，秦桓公派医缓前往。他还没到，景公梦见病化作两个小孩，一个说他是良医，恐怕会伤到我们，另一个说我们躲到肓之上、膏之下，他能奈我何。医缓到后诊断说病在“肓之上，膏之下”，攻之不可，达之不及，药不至焉，不可为也。景公称他为良医，厚礼送回。“病入膏肓”即出于此。'],
  ['吕相', 'jin', '', '?–?', '晋国大夫，魏锜之子，又称魏相。前 580 年晋秦令狐之盟后，秦桓公归国即背盟，联合狄、楚谋晋。前 578 年晋厉公派他出使秦国宣读绝交书，从秦穆公与晋献公的交好说起，历数秦国背盟弃好的种种罪状，文辞铿锵，史称《吕相绝秦》。随后晋率诸侯之师在麻隧大败秦军。'],
  ['栾书', 'jin', '', '?–前573', '谥武子，晋国中军元帅，执政晋国十余年。前 585 年救郑，不与楚战而还，听取知庄子、范文子、韩献子之言，被赞为“从善如流”。前 575 年鄢陵之战任中军将，主张固垒而待楚军疲惫，郤至力主速战。战后晋厉公骄奢，杀三郤，他与中行偃趁厉公出游时将其囚禁、杀死，从周迎回十四岁的公子周立为晋悼公。'],
  ['范文子', 'jin', '', '?–前574', '名士燮，范武子士会之子，晋国中军佐。前 575 年鄢陵之战前，他认为只有圣人能外宁而无内忧，若非圣人，外宁必有内忧，不如留着楚国作为外患，使国内警惕团结，主张不战。战后晋厉公骄侈，他预感内乱将起，回国后让祝宗为他祈死，说“君骄侈而克敌，是天益其疾也，难将作矣”，次年夏去世，不久晋国果然内乱。'],
  ['吕锜', 'jin', '', '?–前575', '即魏锜，魏犨之子，吕相之父，晋国大夫，食邑于吕。前 597 年邲之战前曾请求出使楚营挑战。前 575 年鄢陵之战前，他梦见射月，中之，自己却退入泥中，占卜说月是异姓，必是楚王，射中楚王而自己退入泥中，也必死。战中他果然一箭射中楚共王的眼睛，楚共王召来神射手养由基，给他两支箭，养由基射吕锜，正中脖颈，伏弢而死。'],
  ['郤至', 'jin', '', '?–前574', '郤克的族侄，晋国新军佐，能言善辩。前 575 年鄢陵之战他力主速战，认为楚军有六间可乘，战中三次遇到楚共王，见了楚王都下车免胄，快步而行以示敬意，楚王派人赠弓问候。战后他自矜其功，又派人到周王室夸耀，得罪栾书等人。晋厉公欲去群大夫，与他有隙的宦者胥童等进谗，他与郤锜、郤犨同被厉公所杀，三郤之族被灭。'],
  ['苗贲皇', 'jin', '', '?–?', '楚国令尹斗越椒之子，前 605 年若敖氏之乱被楚庄王平定后，他逃奔晋国，晋人给他苗地作为食邑，故称苗贲皇。前 575 年鄢陵之战，他在晋厉公身边，说楚之良兵在中军王族，请分晋军精锐攻击楚国的左右两翼，再集中三军攻打楚王亲兵，必然大败楚军。晋厉公采纳，楚军大败。'],
  ['中行偃', 'jin', '', '?–前554', '即荀偃，荀庚之子，谥献子。前 573 年与栾书合谋囚杀晋厉公，迎立悼公。悼公时任中军将，执政晋国。前 559 年率诸侯之师伐秦，下令“鸡鸣而驾，塞井夷灶，唯余马首是瞻”，下军将栾黡不服，说“余马首欲东”，引兵东归，诸侯之师只得撤回，史称“迁延之役”。前 555 年又率诸侯伐齐，平阴之战大败齐军，次年在回师途中病死，死不瞑目，范宣子许诺继续伐齐，眼睛才合上。'],
  ['荀罃', 'jin', '', '?–前560', '即知罃，荀首之子，谥武子。前 597 年邲之战被楚军俘虏，在楚九年，前 588 年晋楚交换俘虏才归晋，归国前楚共王问他如何报答，他不卑不亢地说要尽臣职，以死报国，楚王赞叹“晋未可与争”。悼公时任中军元帅，提出“三分四军”之策，把晋军分为三部，轮番出击，楚军来则退，楚军去则来，三驾而楚疲于奔命，郑国终于服晋。'],
  ['魏绛', 'jin', '', '?–?', '谥庄子，魏犨之孙，晋悼公的重臣。前 570 年任中军司马，悼公之弟杨干的车乱了行列，他斩其仆人以正军法，悼公大怒，后来醒悟，称赞他执法严明。他提出“和戎五利”，主张与诸戎讲和，以货易土，悼公派他与诸戎结盟，安定了北方。悼公复霸后把郑国所赠的女乐的一半赐给他，他推辞说“**左传|居安思危**，思则有备，有备无患”。'],
  ['栾黡', 'jin', '', '?–?', '谥桓子，栾书之子，晋国下军将，为人骄横。前 559 年中行偃率诸侯伐秦，下令“唯余马首是瞻”，他不服，说“**左传|余马首欲东**”，引所部东归，诸侯之师只得撤回，史称迁延之役。他的弟弟栾鍼与范宣子之子范鞅冲入秦军，栾鍼战死，范鞅生还，他认为是范鞅害死弟弟，要杀范鞅，范鞅出奔秦国，栾、范两家由此结仇。'],
  ['师旷', 'jin', '', '?–?', '晋国乐师，字子野，盲人，精于音律，能以琴音辨吉凶。晋平公铸大钟，乐工都说音调和谐，只有他说不和谐。前 555 年平阴之战，他听到齐军营中有鸟乌之声，断定齐军已经夜遁。楚国伐郑时，他说南风不竞，多死声，楚必无功。他常以音乐、比喻劝谏晋平公，曾说“少而好学，如日出之阳；壮而好学，如日中之光；老而好学，如炳烛之明”。'],
  ['叔向', 'jin', '', '?–?', '名羊舌肸，晋国大夫，以博学和直言著称，与郑子产、齐晏婴同时，常相往来论政。'],
  ['范宣子', 'jin', '', '?–前548', '名士匄，范文子之子，晋国中军元帅。前 575 年鄢陵之战，楚军清晨迫近晋营布阵，他献计“塞井夷灶，陈于军中，而疏行首”，使晋军得以列阵。晋平公时执政，曾铸刑鼎（一说为后来的范献子），加重诸侯朝聘的贡赋，被郑国子产写信劝止。他与栾氏结怨，前 552 年驱逐栾盈，前 550 年栾盈潜回曲沃作乱，他奉晋平公据固宫而守，平定栾氏之乱。'],
  ['栾盈', 'jin', '', '?–前550', '谥怀子，栾黡之子，母亲是范宣子之女栾祁。他好施得士，士多归之，范宣子忌惮他，加上栾祁诬告他将作乱，前 552 年被驱逐出奔楚国，后转到齐国。前 550 年齐庄公以送女陪嫁为名，把他和他的私属藏在篷车中送回曲沃，他率曲沃之甲白天攻入绛都，魏献子原本答应相助，被范鞅劫持改变立场，他兵败退回曲沃，城破被杀，栾氏灭族。'],
  // 秦
  ['秦穆公', 'qin', '', '?–前621', '名任好，秦德公之子，春秋时期秦国最有作为的君主。他以五羖羊皮赎回百里奚，又用蹇叔、由余、丕豹、公孙支等人。他三次为晋国立君，晋饥时泛舟输粟，韩原之战俘获晋惠公后又放归，后护送重耳回国即位。殽之战秦军惨败，他素服郊迎，不替孟明，此后终于济河焚舟、封殽尸而还；又用由余之谋伐戎，益国十二，开地千里，“**遂霸西戎**”。死后以三良等一百七十七人殉葬，国人作《黄鸟》哀之。'],
  ['百里奚', 'qin', '', '?–?', '原为虞国大夫，虞亡后作为陪嫁之臣入秦，逃往楚国，被秦穆公以五张羊皮赎回，号“五羖大夫”，执掌国政。'],
  ['蹇叔', 'qin', '', '?–?', '百里奚的好友，曾在百里奚落魄时收留他，几次劝阻他投奔齐公子无知、周王子颓、虞君，百里奚因此几次免祸。百里奚为秦相后把他推荐给秦穆公，任为上大夫。前 627 年秦穆公想偷袭郑国，他力谏劳师袭远必败，穆公不听，他哭着送别出征的儿子，说“**左传|晋人御师必于殽**”，殽有二陵，我将在那里收你的尸骨。秦军果然在殽山全军覆没。'],
  ['孟明视', 'qin', '', '?–?', '名视，字孟明，百里奚之子，秦军主帅。前 627 年率军偷袭郑国，在滑国遇到郑商人弦高犒师，知郑有备，灭滑而还，在殽山被晋军伏击，全军覆没，与西乞术、白乙丙同被俘，靠文嬴劝说晋襄公放还。秦穆公素服郊迎，不废其职。前 625 年彭衙之战再败，他增修国政，重施于民。前 624 年随穆公伐晋，济河焚舟，取王官及郊，晋人不敢出，于是封殽尸而还。'],
  ['西乞术', 'qin', '', '?–?', '秦国将领，一说为蹇叔之子。前 627 年与孟明视、白乙丙率军偷袭郑国，在殽山中晋军埋伏，全军覆没，三帅被俘，靠文嬴说情获释。前 626 年他出使鲁国，以礼辞让，被鲁人称赞为“君子”。此后随孟明视多次伐晋，最终封殽尸而还。'],
  ['白乙丙', 'qin', '', '?–?', '秦国将领，名丙，一说为蹇叔之子。出征前蹇叔哭送他，说“晋人御师必于殽”。前 627 年与孟明视、西乞术率军袭郑，殽之战中被晋军俘获，后靠文嬴说情获释归秦，又随孟明视参与彭衙之战和王官之役。'],
  ['由余', 'qin', '', '?–?', '先世为晋人，逃亡入戎，能说晋语，为戎王之臣。戎王听说秦穆公贤明，派他出使秦国观察。秦穆公向他夸耀宫室积聚，他说使鬼为之则劳神，使人为之亦苦民；又与穆公论治国之道，认为戎夷上下一体，无礼法之烦而治。穆公认为他是贤人，用内史廖之计，送戎王女乐、留由余不归，使戎王与由余离心，由余于是降秦，为秦谋划伐戎，助穆公益国十二，“开地千里，遂霸西戎”。'],
  ['穆姬', 'qin', '', '?–?', '晋献公之女，太子申生的同母姐，嫁秦穆公为夫人，生太子罃（秦康公）。弟弟夷吾回国即位时，她曾嘱咐他善待群公子、接纳流亡的贾君。前 645 年韩原之战，晋惠公被秦俘获押回秦国，她带着太子罃、弘及女儿简璧登台履薪，派人穿着丧服迎接穆公，说若晋君朝以入，则婢子夕以死，穆公于是把晋惠公安置在灵台，后来放其回国。'],
  ['怀嬴', 'qin', '', '?–?', '秦穆公之女，先嫁在秦为质的晋太子圉。前 638 年太子圉要私自逃回晋国，邀她同行，她说跟你走是弃君命，又不敢告发，于是不走也不泄露。重耳到秦国后，秦穆公把五个宗女嫁给他，怀嬴也在其中，她捧匜沃盥，重耳洗完挥手让她走开，她发怒说“秦晋匹也，何以卑我”，重耳只好降服囚身谢罪，后称文嬴。殽之战后，她劝晋襄公放还秦国三帅。'],
  ['秦桓公', 'qin', '', '?–前577', '名荣，秦共公之子。前 594 年秦攻晋，在辅氏被晋大败。前 580 年与晋厉公约在令狐会盟，晋厉公先到，他却不肯渡河，派大夫史颗到河东与晋盟，回国后即背弃盟约，与狄人和楚国谋划攻晋。前 578 年晋派吕相宣读绝交书，率诸侯之师在麻隧大败秦军，俘虏秦将成差及不更女父。在位二十七年。'],
  // 楚
  ['楚成王', 'chu', '', '?–前626', '名頵，在位四十六年，北上与齐桓公争衡，盂之会执宋襄公，泓之战败宋，厚待流亡的重耳。城濮之战后楚北进受挫，晚年被太子商臣逼死。'],
  ['子玉', 'chu', '', '?–前632', '名成得臣，若敖氏，楚国令尹，骁勇刚愎。他在蔿地治兵，一天之内鞭打七人、贯穿三人之耳，蔿贾预言他刚而无礼，带兵超过三百乘必败。前 632 年楚围宋，晋文公伐曹卫以救宋，楚成王命他撤兵，他坚持要战，请求成王给予少量兵力，成王只给了西广、东宫和若敖之六卒。城濮之战楚军大败，他率残部退至连谷，成王派人责问，他自杀而死。晋文公闻讯大喜，说“莫余毒也已”。'],
  ['子文', 'chu', '', '?–?', '名斗穀於菟，楚国令尹，若敖氏。相传他生下后被弃于云梦泽，有老虎哺乳，楚人称乳为穀、虎为於菟，因以为名。他三次出任令尹而无喜色，三次罢官而无愠色，楚国财政困难时毁家纾难，捐出家财以助国用。他执政二十八年，辅佐楚成王北上与齐、晋争衡。晚年让位于子玉，以为子玉可以大用，子玉在城濮大败后自杀。孔子称他“忠矣”。'],
  ['楚穆王', 'chu', '', '?–前614', '名商臣，楚成王的太子。成王后来想废他改立王子职，他听到风声，向老师潘崇求计，潘崇教他宴请成王的妹妹江芈而故意不敬，江芈怒骂“宜君王之欲杀女而立职也”，证实了传言。前 626 年他以宫甲围成王，成王请求吃了熊掌再死，他不许，成王自缢。即位后以潘崇为太师，在位十二年，灭江、六、蓼，兼并群舒，楚势复振。'],
  ['潘崇', 'chu', '', '?–?', '楚国太子商臣的师傅。商臣听说成王要废他，问计于潘崇，潘崇教他宴请成王之妹江芈并故意不敬以试探，证实了废立之事。他又问商臣能否事奉王子职、能否出奔、能否行大事，商臣说能行大事，于是二人以宫甲围成王，逼其自缢。穆王即位后，把自己做太子时的宫室财物赐给他，任为太师，掌环列之尹。'],
  ['楚庄王', 'chu', '', '?–前591', '名旅，楚穆王之子，春秋五霸之一。即位三年不出号令，日夜为乐，伍举以大鸟三年不蜚不鸣讽谏，他说“三年不蜚，蜚将冲天；三年不鸣，**鸣将惊人**”，于是亲政，诛杀数百人，进用数百人。他灭庸，平若敖氏之乱，伐陆浑之戎时观兵周疆，问鼎之大小轻重；县陈而后听申叔时之谏复封之；前 597 年邲之战大败晋军，又围宋九月，宋人易子而食，与盟而还，称霸中原。'],
  ['伍举', 'chu', '', '?–?', '楚国大夫，又称椒举，伍子胥的祖父。以“三年不蜚”的隐语讽谏楚庄王。'],
  ['孙叔敖', 'chu', '', '?–?', '名蔿敖，楚国期思人。传说他少年时见到两头蛇，听说见者必死，怕别人再看见，把蛇杀死埋掉，母亲说你有阴德，必不死。楚庄王任为令尹，他施教导民，上下和合，主持修建期思陂、芍陂等水利工程。前 597 年邲之战中，他见晋军先縠部渡河，力主进攻，说“宁我薄人，无人薄我”，大败晋军。他为官清廉，死后家无余财，儿子靠打柴为生，优孟扮作他的模样劝谏楚王，其子才得封地。后世奉为循吏典范。'],
  ['斗越椒', 'chu', '', '?–前605', '字子越，若敖氏，楚国令尹子文的侄子。他出生时子文就说“是子也，熊虎之状，而豺狼之声，弗杀，必灭若敖氏矣”，临终又嘱咐族人他一旦执政就逃走。他先任司马，杀令尹斗般后自任令尹。前 605 年他起兵攻楚庄王，两军战于皋浒，他两箭射中庄王车辕和车盖，楚军惊惧，庄王说先君得三支神箭，他已射完两支，于是鼓而进兵，他中箭被杀，若敖氏族灭。'],
  ['申叔时', 'chu', '', '?–?', '楚国大夫。前 598 年陈国夏征舒弑陈灵公，楚庄王讨伐夏征舒，车裂之，随后把陈国设为楚县，群臣都来道贺，只有他出使齐国回来后不贺。庄王问他，他以“蹊田夺牛”为喻：有人牵牛践踏别人的田，田主就夺了他的牛，牵牛践田确实有罪，但夺牛之罚太重了；诸侯跟随您讨伐有罪，现在却贪其富而县之，怎么号令天下？庄王于是恢复陈国。'],
  ['申舟', 'chu', '', '?–前595', '名无畏，楚国大夫，又称文之无畏。前 617 年楚穆王在孟诸田猎，宋昭公违命，他鞭打宋昭公的仆人以示惩罚，与宋结怨。前 595 年楚庄王派他出使齐国，故意命令他不向宋国借道，他说郑昭宋聋，晋使不害，我则必死，庄王说杀了你我就伐宋。他把儿子申犀托付给庄王后出发，经过宋国时被宋执政华元所杀，楚庄王闻讯投袂而起，发兵围宋。'],
  ['子反', 'chu', '', '?–前575', '名公子侧，楚庄王之弟，楚国司马。前 594 年楚围宋九月，宋人易子而食，宋华元夜入楚营，登上他的床，以宋国实情相告，他与华元私订和约，楚军退三十里，宋楚讲和。他与令尹子重都想得到夏姬，被巫臣带走，二人杀巫臣之族，此后吴国被巫臣教以车战，他一年七次奔命。前 575 年鄢陵之战，楚败后他醉酒不能应召议事，楚共王连夜撤军，他自杀谢罪。'],
  ['子重', 'chu', '', '?–前570', '名公子婴齐，楚庄王之弟，楚国令尹。邲之战时为左军将。前 584 年起吴国在巫臣教唆下屡次攻楚，子重与子反疲于奔命。前 575 年鄢陵之战任左军将，楚败。前 570 年他亲率楚军伐吴，攻取鸠兹，至于衡山，派邓廖率精兵深入，被吴军截击，楚军大败，吴人又攻取驾邑，楚人归罪于他，他忧愤成疾，发心疾而死。'],
  ['巫臣', 'chu', '', '?–?', '屈氏，名巫，字子灵，楚国申公。楚庄王讨伐夏征舒后想纳夏姬，他以“贪色为淫”劝阻，子反想娶夏姬，他又说夏姬是不祥之人。后来他设计让夏姬回郑国，自己借出使齐国之机，带着夏姬投奔晋国，晋以邢为其食邑。子重、子反杀其族人，他发誓“余必使尔罢于奔命以死”，于是出使吴国，带去战车，教吴人乘车、射御、战阵，让儿子屈狐庸留吴为行人，吴国从此与楚为敌。'],
  ['楚共王', 'chu', '', '前600–前560', '名审，楚庄王之子，十岁即位。前 575 年为救郑，亲率楚军与晋战于鄢陵，被晋将吕锜一箭射中眼睛，召养由基射杀吕锜，战后司马子反醉酒不能应召，他连夜撤军，楚军大败。此后晋悼公复霸，三驾而楚不能与争。他在位三十一年，临终自认不德，让大夫们给他定恶谥“灵”或“厉”，令尹子囊说他知过能改，谥为“共”。'],
  ['养由基', 'chu', '', '?–?', '楚国大夫，神射手。据《战国策》记载，他离柳叶百步而射之，百发百中，“百步穿杨”即出于此。前 575 年鄢陵之战前，他与潘党比射，一箭射穿七层皮甲，楚共王怒其恃艺。战中共王被吕锜射伤眼睛，召他来，给他两支箭，他一箭射中吕锜脖颈，吕锜伏在弓袋上而死，他把剩下的一支箭还给共王复命。'],
  ['屈建', 'chu', '', '?–前545', '字子木，楚国令尹，屈到之子。前 548 年楚伐舒鸠时，他率军击败吴军，次年随楚康王伐郑。前 546 年与晋国执政赵武在宋国主持弭兵之会，盟会时楚人衷甲（在衣内穿甲），他力争先歃血，晋人让楚先歃。会后晋楚之间四十余年没有大战，中原诸侯“晋楚之从交相见”。次年去世。'],
  // 齐
  ['齐桓公', 'qi', '', '?–前643', '名小白，春秋第一位霸主，任用管仲，九合诸侯，一匡天下（详见《齐桓称霸》）。晚年宠信易牙、竖刁，死后五公子争立，尸虫出于户。'],
  ['易牙', 'qi', '', '?–?', '齐桓公的宠臣，善于烹调，据说曾烹子以献桓公。桓公死后与竖刁作乱，立公子无亏。'],
  ['竖刁', 'qi', '', '?–?', '齐桓公的宠臣，自宫以近桓公。与易牙共同作乱。'],
  ['齐孝公', 'qi', '', '', ''],
  ['齐姜', 'qi', '', '?–?', '齐桓公的宗女。重耳流亡到齐国，齐桓公把她嫁给重耳，送马二十乘，重耳安于齐国，不想离开。随从们在桑树下谋划带重耳离开，被采桑的侍女听到，告诉了齐姜，齐姜杀侍女灭口，对重耳说你有四方之志，我已经知道了，劝他离开。重耳说“民生安乐，谁知其他”，她说“行也，怀与安，实败名”，与狐偃合谋把重耳灌醉，载出齐国。'],
  ['齐顷公', 'qi', '', '?–前582', '名无野，齐惠公之子，齐桓公之孙。前 592 年晋国郤克出使齐国，他让母亲萧同叔子在帷后观看，萧同叔子笑郤克跛足，郤克发誓报仇。前 589 年他伐鲁、卫，晋派郤克率军救援，鞍之战中他说“余姑翦灭此而朝食”，不给马披甲就驰入晋军，大败，被韩厥追及，靠车右逢丑父与他换位、借取水之名才得以脱身，被迫归还侵占的鲁、卫土地。此后他弛苑囿、薄赋敛，恤孤问疾，国人称颂。'],
  ['逢丑父', 'qi', '', '?–?', '齐顷公的车右。前 589 年鞍之战齐军败退，韩厥在后追赶，他与顷公换了位置。车被树木挂住，韩厥追上，以臣礼进献酒璧，他假扮国君，命顷公下车去华泉取水，顷公趁机逃脱，他被韩厥俘虏献给郤克。郤克要杀他，他大呼“自今无有代其君任患者，有一于此，将为戮乎”，郤克认为他忠勇，说“人不难以死免其君，我戮之不祥”，赦免了他。'],
  ['齐灵公', 'qi', '', '?–前554', '名环，齐顷公之子。在位期间先后灭莱国，扩地至胶东；他屡次伐鲁，前 555 年晋率诸侯伐齐，他在平阴迎战，晋人虚张声势，以旗帜、战车拖柴扬尘，他畏惧夜遁，齐军大败，诸侯之师一直攻到临淄城下。他废太子光，改立宠姬戎子所养的公子牙，临终前崔杼迎回太子光即位，杀公子牙。'],
  ['晏弱', 'qi', '', '?–前556', '谥桓子，晏婴之父，齐国大夫。前 567 年率军灭莱国，迁莱君于郳，把莱的宗器献于襄宫，齐国由此东拓至胶东半岛。前 590 年他曾作为使者赴晋参加断道之会，途中被晋人拘执，后逃回。前 556 年去世，晏婴居丧尽礼，粗衰斩，苴绖带，杖，菅屦，食粥，居倚庐，大夫说这不合大夫之礼，晏婴说“唯卿为大夫”。'],
  ['齐庄公', 'qi', '', '?–前548', '名光，齐灵公之子，原为太子，被灵公废黜，灵公病重时由崔杼迎回即位。他好勇，设立勇爵以待勇士，接纳晋国逃亡的栾盈，前 550 年用陪嫁的篷车把栾盈送回曲沃作乱，又亲自伐晋，攻取朝歌，登太行而还。他屡次到崔杼家与崔杼之妻棠姜私通，还把崔杼的帽子赐给别人。前 548 年崔杼称病，他借探病之名又去崔家，被崔杼的家兵杀死。'],
  ['崔杼', 'qi', '', '?–前546', '谥武子，齐国大夫，齐丁公之后。齐灵公病重时，他迎回废太子光即位为庄公。他娶棠公遗孀棠姜，庄公与棠姜私通，前 548 年他称病不朝，趁庄公来家时伏兵杀之，立庄公的异母弟为景公，自任右相，与庆封专齐国之政。太史书“崔杼弑其君”，他杀太史，太史之弟两人接着照写，都被杀，第三个弟弟仍照写，他只得作罢。后崔氏诸子争立，庆封趁机灭崔氏，他自缢而死。'],
  ['棠姜', 'qi', '', '?–?', '齐国棠邑大夫棠公之妻，东郭偃之姊，美貌。棠公死后，东郭偃为崔杼驾车去吊丧，崔杼见到棠姜，想娶她，占卜得“困”之“大过”，陈文子说凶，崔杼说是寡妇，先夫已经承担了凶兆，于是娶之。齐庄公与她私通，多次到崔家，前 548 年崔杼借此杀庄公。后崔氏内乱，棠姜自缢而死。'],
  ['晏婴', 'qi', '平仲', '?–前500', '字平仲，晏弱之子，历仕灵公、庄公、景公三朝，节俭力行，以善谏著称。崔杼弑庄公时“**左传|社稷是主**”，不死不亡，枕尸而哭。'],
  // 宋
  ['宋襄公', 'song', '', '', ''],
  ['子鱼', 'song', '', '?–?', '名目夷，宋桓公的庶长子，宋襄公的庶兄，宋国司马。襄公做太子时想让位于他，他说“能以国让，仁孰大焉”，辞不受。襄公图霸时他屡次劝谏，说小国争盟是祸，盂之会前说“祸其在此乎”。泓之战中两次劝襄公趁楚军半渡未成列时出击，襄公不听，大败，战后他批评襄公“**左传|君未知战**”，说勍敌之人隘而不列，天赞我也，伤未及死，如何勿重。'],
  ['华元', 'song', '', '?–?', '宋国右师，执政宋国四十余年。前 607 年大棘之战与郑交战，因羊斟怨恨没有分到羊羹，驾车驰入郑军，被俘，后逃回。前 595 年杀楚使申舟，引来楚军围宋九月，宋国粮尽，易子而食，他夜入楚营，登上子反之床，说敝邑易子而食，析骸以爨，但城下之盟有以国毙不能从也，请退三十里，促成宋楚之盟。后来他又促成前 579 年第一次晋楚弭兵。'],
  ['向戌', 'song', '', '?–?', '宋国左师，宋桓公的后代。他与晋国执政赵武、楚令尹屈建都交好，前 546 年发起弭兵之会，奔走晋、楚、齐、秦诸国，说服各国同意，十四国大夫会于宋国西门之外，订立盟约，晋楚之从交相见。事后他向宋平公请赏，宋平公赐邑六十，他把赐书给子罕看，子罕说兵是用来威慑不轨、昭明文德的，削去其字，他于是辞去赏邑。'],
  ['叔孙豹', 'lu', '', '?–前538', '名豹，谥穆子，又称穆叔，鲁国三桓之一叔孙氏的宗主，长期出使各国，以知礼著称。他曾对晋国范宣子说，所谓不朽，“太上有立德，其次有立功，其次有立言”，“虽久不废”，这就是“三不朽”之说。弭兵之会时，季武子要他降格与邾、滕同列，他坚持鲁是列国，不肯从命。晚年宠信竖牛，竖牛离间他与儿子们，他病重时被竖牛断绝饮食，饿死。'],
  // 郑
  ['郑文公', 'zheng', '', '?–前628', '名踕，郑厉公之子，在位四十五年。重耳流亡经过郑国，他不加礼遇，叔詹劝他要么礼遇、要么杀掉，他都不听。他在齐楚之间摇摆，城濮之战时依附楚国，战后又与晋盟于衡雍。前 630 年晋秦以郑无礼于晋且贰于楚为由围郑，他听佚之狐之言，请出年老的烛之武夜缒出城，说退秦师，晋亦退兵。'],
  ['烛之武', 'zheng', '', '?–?', '郑国老臣，年老不得重用。前 630 年晋秦围郑，佚之狐向郑文公推荐他，他说“臣之壮也，犹不如人；今老矣，无能为也已”，文公自责请罪，他于是夜里用绳子从城上缒下，去见秦穆公，说亡郑以陪邻，“**左传|越国以鄙远**”，君知其难也，若舍郑以为东道主，行李之往来，共其乏困，君亦无所害。秦穆公被说服，与郑结盟，派杞子等三人戍郑而还，晋亦撤兵。'],
  ['弦高', 'zheng', '', '?–?', '郑国商人。前 627 年秦军偷袭郑国，行至滑国，正遇往周贩牛的弦高。他假托郑君之命，先以四张熟牛皮、后以十二头牛犒劳秦军，说寡君听说吾子将步师出于敝邑，敢犒从者；同时派人火速回国报信。郑穆公派人查看秦国戍兵的客馆，他们已束载、厉兵、秣马，于是驱逐杞子等人。秦帅孟明视认为郑已有备，灭滑而还，在殽山被晋军伏击。'],
  ['郑灵公', 'zheng', '', '?–前605', '名夷，郑穆公之子。前 605 年楚人献鼋（大鳖）给他，公子宋和子家入朝时，公子宋的食指动了，说以前每次这样都能尝到异味。进门后见厨师正在解鼋，二人相视而笑，灵公问其故，子家告之，灵公召大夫们吃鼋羹，偏偏召公子宋而不给他吃，公子宋怒，把手指伸进鼎中蘸了尝过离去，“染指”即出于此。灵公大怒要杀公子宋，反被公子宋与子家所杀。'],
  ['公子宋', 'zheng', '', '?–?', '字子公，郑国大夫。“食指动”“染指于鼎”的主角。前 605 年郑灵公故意不给他吃鼋羹，他把手指伸进鼎中蘸了尝后离去，灵公发怒想杀他，他先与子家谋划弑君，子家说畜老犹惮杀之，况君乎，他反过来诬陷子家，子家害怕，只好跟从，二人于这年夏天杀死郑灵公。'],
  ['子家', 'zheng', '', '?–前599', '名公子归生，郑国大夫，郑灵公时与公子宋同执政。前 607 年曾率郑军在大棘之战中击败宋军，俘虏华元。公子宋染指于鼎后谋杀灵公，他起初劝阻，公子宋反诬他，他害怕而从之，二人弑杀郑灵公。《春秋》书“郑公子归生弑其君夷”，君子说他“仁而不武，无能达也”。前 599 年他去世，郑人追究弑君之罪，斫其棺，逐其族。'],
  ['郑襄公', 'zheng', '', '?–前587', '名坚，郑穆公之子，郑灵公之弟，郑灵公被杀后即位。郑国在晋楚之间朝晋暮楚，前 597 年楚庄王围郑十七日，攻破城门，他肉袒牵羊迎接楚王，说孤不天，不能事君，使君怀怒以及敝邑，愿听从发落，楚庄王认为他能下人，必能信用其民，退兵三十里，与郑讲和。晋军来救，在邲被楚大败。'],
  // 周
  ['周襄王', 'zhou', '', '', ''],
  ['王子带', 'zhou', '', '?–前635', '即甘昭公，周惠王之子，周襄王的异母弟，深得惠王与惠后宠爱。前 649 年他召扬、拒、泉、皋、伊、洛之戎攻周，秦、晋伐戎救周，事败后出奔齐国。后被召回，又与襄王所立的狄后私通，前 636 年借狄师攻王，襄王出居于郑，他自立，与狄后居于温。次年晋文公出兵勤王，将他杀死于隰城。'],
  ['王子虎', 'zhou', '', '?–前622', '即王叔文公，周王室卿士。前 632 年城濮之战后，周襄王到践土慰劳晋文公，他与尹氏、内史叔兴父奉命策命晋文公为侯伯，赐大辂之服、戎辂之服、彤弓一、彤矢百、玈弓矢千、秬鬯一卣、虎贲三百人。随后他又主持了践土之盟，盟辞说“皆奖王室，无相害也”。'],
  ['王孙满', 'zhou', '', '?–?', '周王室大夫。前 627 年秦军袭郑经过周的北门，车左车右都脱去头盔下车致敬，随即又跳上车，三百乘皆如此，年少的他看了说秦师轻而无礼，必败。前 606 年楚庄王伐陆浑之戎，观兵于周疆，周定王派他去慰劳，楚庄王问鼎之大小轻重，他回答“**左传|在德不在鼎**”，周德虽衰，天命未改，鼎之轻重，未可问也。'],
  ['周定王', 'zhou', '', '?–前586', '名瑜，周匡王之弟，东周天子。前 606 年楚庄王伐陆浑之戎，至于洛水，观兵于周疆，他派王孙满去慰劳楚军，楚庄王问鼎之大小轻重，王孙满以“在德不在鼎”答之，楚庄王退兵。在位期间周王室已无力号令诸侯，只能周旋于晋、楚之间。在位二十一年。'],
  // 曹、陈、鲁、吴等
  ['曹共公', 'cao', '', '?–前618', '名襄，曹昭公之子。重耳流亡经过曹国，他听说重耳“骈胁”（肋骨连成一片），想看看，趁重耳洗澡时到帘后偷看，大夫僖负羁之妻劝丈夫早作结交。前 632 年晋文公为救宋伐曹，三月攻入曹都，俘虏曹共公，数落他不用僖负羁而乘轩者三百人；后来晋文公生病，曹人侯獳贿赂筮史进言，晋文公才放他回国复位。'],
  ['卫文公', 'weiguo', '', '', ''],
  ['僖负羁', 'cao', '', '?–?', '曹国大夫。重耳流亡到曹国，曹共公无礼偷看其骈胁，他的妻子对他说晋公子的随从都足以相国，晋公子必能回国称霸，诛无礼之国，曹是首当其冲，你何不早些表示好意。他于是派人送去一盘饭，里面藏着玉璧，重耳受饭而还璧。前 632 年晋军攻入曹都，晋文公下令不准进入僖负羁家，并赦免其族人。'],
  ['陈灵公', 'chen', '', '?–前599', '名平国，陈共公之子。他与大夫孔宁、仪行父同时与夏御叔的遗孀夏姬私通，三人都贴身穿着她的衣服在朝堂上开玩笑，大夫泄冶进谏，被孔宁、仪行父杀死。前 599 年他与孔、仪在夏家饮酒，戏谑说夏征舒长得像仪行父，仪行父说也像君，夏征舒受辱，从马厩射杀灵公，孔宁、仪行父逃奔楚国。'],
  ['夏征舒', 'chen', '', '?–前598', '陈国大夫，字子南，夏御叔与夏姬之子。他的母亲与陈灵公、孔宁、仪行父私通，前 599 年三人在他家饮酒时，以他的相貌长得像谁取笑，他忍无可忍，在马厩中埋伏，射杀陈灵公，自立为陈侯。前 598 年楚庄王以讨弑君之贼为名伐陈，将他车裂于栗门。'],
  ['夏姬', 'chen', '', '?–?', '郑穆公之女，嫁陈国大夫夏御叔，生夏征舒，美貌，号称“杀三夫一君一子，亡一国两卿”。夫死后与陈灵公、孔宁、仪行父私通，引发陈国之乱。楚庄王灭夏征舒后想纳她，被巫臣劝止；子反也想娶，又被劝止，于是赐给连尹襄老，襄老战死于邲。巫臣设计让她回郑国，后借出使齐国之机带她投奔晋国，生一女，即后来叔向之妻。'],
  ['叔梁纥', 'lu', '', '?–?', '名纥，字叔梁，鲁国郰邑大夫，以勇力著称。前 563 年晋率诸侯攻偪阳，偪阳人打开城门诱诸侯之士入城，随即放下悬门，他双手托住悬门，让进城的士兵撤出。前 556 年齐军围防邑，他与臧畴、臧贾率甲士三百夜袭齐师，护送臧纥突围后又回守防邑。晚年与颜徵在野合而生孔子，孔子三岁时去世。'],
  ['臧文仲', 'lu', '', '?–前617', '名辰，臧孙氏，鲁国正卿，历事庄、闵、僖、文四公。鲁国饥荒时，他带着鬯圭、玉磬到齐国请求买粮；齐孝公伐鲁，他派展喜以犒师之辞说退齐军，又亲往楚国借兵。六、蓼被楚所灭，他叹息皋陶、庭坚之后从此断了祭祀。他死后，叔孙豹把他的言论作为“立言”不朽的例子；孔子却批评他明知柳下惠贤能而不举荐，又僭越礼制为大龟造华丽的居室，说他“不仁者三，不知者三”。'],
  ['鲁宣公', 'lu', '', '?–前591', '名俀，鲁文公之子，敬嬴所生。文公死后，襄仲（东门遂）杀嫡子恶及其弟视，立他为君。他即位后依附齐国，割济西之田以赂齐，又屡次朝齐。前 594 年“初税亩”，开始按田亩征税，承认了私田的合法性，《左传》说“非礼也，谷出不过藉，以丰财也”。晚年想借晋国之力去掉三桓，未成而死。'],
  ['寿梦', 'wu', '', '?–前561', '吴王，名乘，吴国自他开始称王，与中原交通。前 584 年楚申公巫臣出使吴国，带来战车，教吴人乘车、射御、战阵，吴国开始攻楚伐巢、伐徐，入州来，楚国子重、子反一年七次奔命。前 576 年他与晋、齐、宋等会于钟离，吴国正式进入中原诸侯之列。他有四子，最贤的是幼子季札，他想传位给季札，季札坚辞不受，于是定下兄弟相传、以至季札的约定。'],
];
